"use strict";
// 141 // CATÁLOGO DE EQUIPAMENTOS (gerado do Guia dos Equipamentos 1.4.1)
// excl = classes que podem escolher (vazio = geral). O Especialista (Faz-tudo) escolhe qualquer um.
const EQUIP_CAT = [{"name":"Granada de Fragmentação","tipo":"Lançável","pe":"1","acao":"Ação","mel":2,"desc":"Você arremessa a granada a até 12m. Ela explode num raio de 3m, e cada alvo na área faz um teste de resistência de Destreza (CD 10 + Proef + Des). Na falha, sofre 3d8 de dano perfurante. No sucesso, sofre metade.","melhorias":"Explosão aérea: a granada explode acima do chão, e os alvos na área não recebem o bônus de cobertura parcial no teste.\nSensor de proximidade: você pode deixar a granada no chão como uma armadilha. Ela explode quando um alvo chegar a 2m dela.","qtd":"2"},{"name":"Granada de Contusão","tipo":"Lançável","pe":"0.75","acao":"Ação Bônus","mel":2,"desc":"Você arremessa a granada a até 12m. Ela explode num raio de 4m com uma onda de pressão. Cada alvo na área faz um teste de resistência de Constituição (CD 10 + Proef + Des). Na falha, fica Atordoado até o fim do próximo turno dele. No sucesso, fica Surdo por 1 minuto.","melhorias":"Carga dupla: a granada solta um segundo pulso no início do seu próximo turno, e os alvos ainda na área fazem o teste de novo.\nSeletiva: você escolhe até 2 alvos na área que não são afetados.","qtd":"2"},{"name":"Granada de Luz","tipo":"Lançável","pe":"0.75","acao":"Ação Bônus","mel":2,"desc":"Você arremessa a granada a até 12m. Ela explode num clarão com raio de 6m. Cada alvo na área que possa ver o clarão faz um teste de resistência de Constituição (CD 10 + Proef + Des). Na falha, fica Cego até o fim do próximo turno dele. Um alvo usando NVG ativo tem Desvantagem no teste.","melhorias":"Pulso magnético: o clarão também desliga drones e câmeras na área até o fim do seu próximo turno.\nEstrobo: depois do clarão, a granada pisca por 1 minuto, e quem estiver na área tem Desvantagem em Percepção.","qtd":"2"},{"name":"Granada de Fumaça","tipo":"Lançável","pe":"0.5","acao":"Ação Bônus","mel":2,"desc":"Você arremessa a granada a até 12m. Ela solta uma nuvem com raio de 5m que dura 1 minuto. A área conta como escuridão densa e bloqueia a linha de visão. Vento forte dispersa a nuvem em 1 turno.","melhorias":"Fumaça termal: a nuvem também bloqueia visão térmica e sensores de calor.\nFumaça irritante: quem começar o turno na nuvem faz um teste de resistência de Constituição (CD 12 + Proef + Des). Na falha, tem Desvantagem nos ataques até o fim do turno.","qtd":"3"},{"name":"Faca de Arremesso","tipo":"Lançável","pe":"0.25","acao":"Ação","mel":2,"desc":"Faça um ataque à distância contra um alvo a até 8m, com Precisão igual à sua Proef + Des. Num acerto, ele sofre 1d6 + Des de dano perfurante. O arremesso não faz barulho e não revela a sua posição se você estiver Escondido. Depois do combate, role 1d6 por faca usada: num 4 ou mais, ela é recuperada.","melhorias":"Lâmina balanceada: o alcance sobe para 12m.\nFurtiva: se o ataque for feito com Vantagem, causa +1d4 de dano.","qtd":"3"},{"name":"Coquetel Molotov","tipo":"Lançável","pe":"0.5","acao":"Ação","mel":2,"desc":"Garrafa, pano e combustível. O resto é coragem.\nVocê arremessa a garrafa a até 9m. Ela se quebra num raio de 2m, e cada alvo na área faz um teste de resistência de Destreza (CD 10 + Proef + Des). Na falha, sofre 2d6 de dano incendiário e fica Queimado. No sucesso, sofre metade. A área queima por 1 minuto, e quem entrar nela ou começar o turno nela sofre 1d4 de dano incendiário.","melhorias":"Garrafa grande: o raio sobe para 3m.\nMistura grudenta: o alvo Queimado precisa de duas Ações para apagar o fogo.","qtd":"2"},{"name":"Bomba de Pregos","tipo":"Lançável","pe":"0.5","acao":"Ação","mel":1,"desc":"Uma bomba caseira e instável. Você arremessa a até 9m, e ela explode num raio de 3m. Cada alvo na área faz um teste de resistência de Destreza (CD 10 + Proef + Des). Na falha, sofre 2d8 de dano perfurante e tem o Deslocamento reduzido em 3m até o fim do próximo turno dele. No sucesso, sofre metade. Se você tirar 1 no d20 ao arremessar, ou se for atingido por dano de fogo com ela equipada, ela explode a 3m de você.","melhorias":"Pavio confiável: a bomba não explode mais por acidente.","qtd":"2"},{"name":"Gás Lacrimogêneo","tipo":"Lançável","pe":"0.75","acao":"Ação","mel":1,"desc":"Você arremessa a granada a até 12m. Ela solta uma nuvem com raio de 4m que dura 1 minuto. Quem entrar na nuvem ou começar o turno nela faz um teste de resistência de Constituição (CD 10 + Proef + Des). Na falha, fica Cego e tem Desvantagem nos ataques até o fim do próximo turno dele. Uma máscara de gás protege contra o efeito.","melhorias":"Nuvem densa: a área também conta como penumbra e atrapalha a visão de quem está fora dela.","qtd":"2"},{"name":"Granada de Rede","tipo":"Lançável","pe":"0.75","acao":"Ação","mel":1,"desc":"Você arremessa a granada a até 9m. Ela abre uma rede de 2m de raio. Cada alvo na área faz um teste de resistência de Destreza (CD 10 + Proef + Des). Na falha, fica Impedido. Para se soltar, o alvo usa uma Ação e faz um teste de Força ou Acrobacia com a mesma CD, ou alguém corta a rede (10 PV).","melhorias":"Rede eletrificada: um alvo preso sofre 1d6 de dano elétrico no início de cada turno dele.","qtd":"1"},{"name":"Granada de Tinta","tipo":"Lançável","pe":"0.5","acao":"Ação Bônus","mel":1,"desc":"Você arremessa a granada a até 12m. Ela estoura num raio de 3m. Cada alvo na área faz um teste de resistência de Destreza (CD 12 + Proef + Des). Na falha, fica coberto de tinta por 1 minuto: não pode ficar Escondido nem se beneficiar de camuflagem, e quem usar visor, NVG ou mira eletrônica fica Cego até usar uma Ação para limpar.","melhorias":"Tinta fluorescente: a tinta também brilha no escuro e em visão térmica.","qtd":"2"},{"name":"\"HARPY\" Arpéu Tático","tipo":"Lançável","pe":"0.75","acao":"Ação","mel":2,"desc":"Você dispara o gancho a até 15m numa superfície que aguente o peso. O cabo suporta até 250kg. Com o cabo preso, você sobe até 10m com uma Ação, sem teste, e pode se balançar sobre um vão de até 5m. O arpéu é recolhido depois do uso e não se gasta.","melhorias":"Motor rápido: subir pelo cabo passa a usar só o seu Deslocamento.\nPonta magnética: o gancho se prende em qualquer superfície de metal, sem precisar de ponto de apoio.","qtd":"1"},{"name":"Estrepes","tipo":"Lançável","pe":"0.25","acao":"Ação Bônus","mel":1,"desc":"Você espalha os estrepes numa área de 3m por 3m a até 6m. Quem entrar na área sem passar devagar faz um teste de resistência de Destreza (CD 12 + Proef + Des). Na falha, sofre 1d4 de dano perfurante e tem o Deslocamento reduzido em 3m até o fim do turno. Um veículo com pneus que passar pela área tem a velocidade reduzida em 50% até trocar os pneus.","melhorias":"Estrepes ocos: os pneus de veículos esvaziam por completo, e o veículo para depois de 1 turno.","qtd":"2"},{"name":"Tirolesa Portátil","tipo":"Lançável","pe":"0.5","acao":"Ação","mel":1,"desc":"Você dispara dois ganchos ligados por um cabo de até 30m entre dois pontos que possa ver. Até ser recolhido, qualquer um pode atravessar o cabo com o seu Deslocamento, a 12m por turno, sem teste. Recolher o cabo leva uma Ação.","melhorias":"Motor: quem usar o cabo atravessa tudo de uma vez, sem gastar Deslocamento.","qtd":"1"},{"name":"Mina de Contusão","tipo":"Armadilha","pe":"0.75","acao":"Ação","mel":1,"desc":"Uma mina de pressão não letal. Quando um alvo pisar nela, ela explode num raio de 3m. Cada alvo na área faz um teste de resistência de Constituição (CD 10 + Proef + Des). Na falha, fica Caído e Surdo por 1 minuto.","melhorias":"Carga atordoante: quem falhar também fica Atordoado até o fim do próximo turno dele.","qtd":"2"},{"name":"Fio de Alarme","tipo":"Armadilha","pe":"0.25","acao":"Ação","mel":1,"desc":"Você estica um fio quase invisível de até 6m. Quando alguém o cruzar sem perceber, você recebe um aviso no seu ponto ou escuta um apito, a até 500m. Notar o fio exige um teste de Percepção (CD 12 + Proef + Des).","melhorias":"Fio armado: você pode ligar o fio a uma granada equipada, que explode quando o fio for cruzado.","qtd":"3"},{"name":"Sensor de Movimento","tipo":"Armadilha","pe":"0.5","acao":"Ação","mel":1,"desc":"Um sensor do tamanho de uma moeda. Por 8 horas, ele avisa você quando algo do tamanho de uma pessoa se move a até 6m dele, a até 1km de distância.","melhorias":"Identificador: o sensor também diz quantos alvos passaram e se eram humanos, animais ou máquinas.","qtd":"3"},{"name":"Pote de Fumaça Remoto","tipo":"Armadilha","pe":"0.25","acao":"Ação","mel":1,"desc":"Você esconde o pote num ponto e aciona com uma Ação Bônus a até 100m. Ele solta uma nuvem de fumaça com raio de 5m que dura 1 minuto, como a Granada de Fumaça.","melhorias":"Gatilho de pressão: o pote também pode ser acionado quando alguém pisar nele.","qtd":"2"},{"name":"Arame Farpado em Rolo","tipo":"Armadilha","pe":"0.5","acao":"Ação","mel":1,"desc":"Você desenrola o arame numa linha de até 6m. Quem entrar nele ou tentar atravessar faz um teste de resistência de Destreza (CD 12 + Proef + Des). Na falha, sofre 1d6 de dano cortante e fica Impedido até usar uma Ação para se soltar. Atravessar devagar, gastando o dobro do Deslocamento, não exige teste, mas causa 1d4 de dano.","melhorias":"Concertina: o arame cobre uma linha de 12m.","qtd":"2"},{"name":"Celular Modificado","tipo":"Bateria (Ferramenta de hacking)","pe":"0.5","acao":"Ação","mel":1,"desc":"Um celular comum por fora. Funciona como ferramenta de hacking com alcance de 9m e +0 no teste de invasão. Ele passa por objeto civil numa revista, e você tem Vantagem para escondê-lo. Ocupa uma mão enquanto você invade.","melhorias":"Bateria extra: uma vez por descanso curto, o primeiro Acessar do turno não gasta a sua Ação, só a Ação Bônus."},{"name":"NVG","tipo":"Bateria","pe":"0.75","acao":"Ação Bônus","mel":2,"desc":"Óculos de visão noturna. Enquanto estiverem ligados, você enxerga no escuro até 30m como se fosse penumbra. Eles duram 12 horas por carga completa. Enquanto usar o NVG, você não pode usar a mira da arma, e flashbangs e clarões dão Desvantagem nos seus testes contra eles.","melhorias":"Tamanho reduzido: você pode usar a mira da arma com o NVG ligado.\nFiltro de luminosidade: você não tem mais Desvantagem contra clarões."},{"name":"Visor Térmico","tipo":"Bateria","pe":"1","acao":"Ação Bônus","mel":1,"desc":"Um monóculo que mostra o calor dos corpos e motores até 30m. Enquanto estiver ligado, fumaça comum e escuridão não escondem alvos de você, e você vê quem estiver atrás de cobertura Leve. Ele dura 4 horas por carga completa.","melhorias":"Resfriamento: o visor também mostra rastros de calor de até 10 minutos atrás."},{"name":"Detector de Minas","tipo":"Bateria","pe":"0.5","acao":"Ação","mel":1,"desc":"Você varre o chão à sua frente. Você descobre armadilhas, minas e objetos de metal enterrados a até 3m, e tem Vantagem nos testes de Sabotagem para desarmar armadilhas que encontrou com ele.","melhorias":"Varredura larga: o alcance sobe para 6m."},{"name":"Máscara de Gás","tipo":"Vestido","pe":"0.5","acao":"Ação","mel":2,"desc":"Você fica imune a gases inalados, como fumaça irritante, gás lacrimogêneo e gás sedativo, e não fica Cego por gás. O filtro dura 12 horas.","melhorias":"Filtro químico: você também tem Vantagem nos testes de resistência contra venenos inalados e agentes biológicos.\nRespirador: você respira debaixo d'água ou em ambientes sem ar por até 10 minutos."},{"name":"Capacete Balístico","tipo":"Vestido","pe":"0.5","acao":"Ação Livre","mel":2,"desc":"Um capacete de kevlar com suporte para acessórios. Você tem +1 de CA contra ataques que caiam na Cabeça num acerto crítico e reduz em 2 o dano de quedas e estilhaços.","melhorias":"Trilho lateral: o capacete aceita um NVG ou um Visor Térmico sem ocupar as mãos para ligar ou desligar.\nProtetor auricular: você não fica Surdo por explosões."},{"name":"Joelheiras e Cotoveleiras","tipo":"Vestido","pe":"0.25","acao":"Ação Livre","mel":1,"desc":"Proteção para cair, deslizar e se jogar no chão. Ficar Caído de propósito não gasta Deslocamento, e se levantar custa só um terço dele.","melhorias":"Deslizamento: uma vez por turno, você pode deslizar 3m até uma cobertura sem provocar ataques de oportunidade."},{"name":"Prótese de Braço Reforçada","tipo":"Vestido","pe":"1.5","acao":"Ação Livre","mel":2,"desc":"Um braço mecânico instalado no lugar do original. Você tem Vantagem nos testes de Força feitos com esse braço, e ataques desarmados com ele causam 1d6 + For. A prótese é um Sistema e pode ser invadida, usando o seu Firewall pessoal.","melhorias":"Lâmina retrátil: o braço tem uma lâmina que funciona como uma arma branca Leve e não pode ser desarmada.\nCompartimento oculto: o braço guarda um Item de Bolso ou um pente que não aparece numa revista."},{"name":"Pernas Cibernéticas","tipo":"Vestido","pe":"2","acao":"Ação Livre","mel":2,"desc":"Pernas mecânicas de alto desempenho. O seu Deslocamento sobe 3m, você salta o dobro da distância normal e não sofre dano de quedas de até 6m. As pernas são um Sistema e podem ser invadidas.","melhorias":"Amortecedor: você não sofre dano de quedas de até 12m.\nArranque: uma vez por turno, você pode usar Disparada como Ação Bônus."},{"name":"Implante Ocular","tipo":"Vestido","pe":"1.5","acao":"Ação Livre","mel":2,"desc":"Um olho cibernético com zoom e filtros. Você enxerga até 300m com detalhe, tem Vantagem em Percepção baseada em visão e pode alternar entre visão normal, noturna e térmica com uma Ação Bônus. O olho é um Sistema e pode ser invadido.","melhorias":"Leitura de ameaça: com uma Ação Bônus, você descobre a arma, o colete e se um alvo à vista tem implantes.\nProteção anticlarão: você é imune a ficar Cego por clarões."},{"name":"Wingsuit Tático","tipo":"Vestido","pe":"1","acao":"Ação","mel":1,"desc":"Um traje de planagem dobrável. Ao saltar de pelo menos 30m de altura, você plana até 4 vezes a altura do salto e pousa sem dano. Vestir e abrir o traje leva uma Ação.","melhorias":"Paraquedas de emergência: se você cair de mais de 6m sem planar, o paraquedas abre sozinho e você não sofre dano."},{"name":"Cinto Tático","tipo":"Vestido","pe":"0.25","acao":"Ação Livre","mel":1,"desc":"Um cinto com porta-objetos. A sua Carga máxima sobe 2, e pegar um item que esteja no cinto não gasta Ação.","melhorias":"Porta-granada: você saca uma granada ou um Lançável do cinto sem gastar Ação."},{"name":"Fita de Proteção Neural","tipo":"Vestido","pe":"2.5","acao":"Ação Livre","mel":2,"desc":"Uma fita fina amarrada no braço ou no cabelo. Parece enfeite até o gás chegar.\nUma fita de tecido condutor com um microfiltro neural. Você tem Vantagem nos testes de resistência contra os estados Amedrontado, Atordoado, Cego, Congelado, Envenenado, Paralisado e Surdo. Uma vez por descanso longo, quando falhar num teste contra um desses estados, você pode passar no lugar.","melhorias":"Tecido duplo: o sucesso garantido pode ser usado duas vezes por descanso longo.\nFiltro de PVon: você também tem Vantagem nos testes contra efeitos que causam perda de Pontos de Vontade."},{"name":"Rebreather de Mergulho","tipo":"Vestido","pe":"0.75","acao":"Ação","mel":1,"desc":"Um respirador de circuito fechado que não solta bolhas. Você respira debaixo d'água por 1 hora e nada com o seu Deslocamento normal. Quem estiver na superfície tem Desvantagem para notar você.","melhorias":"Visor de mergulho: você enxerga debaixo d'água até 30m, mesmo em água turva."},{"name":"Spray Hemostático","tipo":"Consumível","pe":"0.5","acao":"Ação Bônus","mel":1,"desc":"Você borrifa o spray num ferimento seu ou de um aliado a até 1,5m. O alvo recupera 1d8 pontos de vida e, se tiver um ferimento crítico, ele para de piorar até ser tratado.","melhorias":"Fórmula de campo: a cura sobe para 1d8 + Sab.","qtd":"3"},{"name":"Gel para Queimaduras","tipo":"Consumível","pe":"0.5","acao":"Ação","mel":1,"desc":"Você passa o gel em você ou num aliado a até 1,5m. O estado Queimado acaba, e o alvo recupera 1d6 pontos de vida.","melhorias":"Gel refrigerante: o alvo também tem resistência a dano incendiário até o fim do próximo turno dele.","qtd":"2"},{"name":"Ração de Combate","tipo":"Consumível","pe":"0.25","acao":"Ação","mel":1,"desc":"Uma refeição completa e compacta. Comer uma ração conta como uma refeição para as regras de Fome e Sede. Durante um descanso curto, quem comer uma ração recupera 1d4 PV a mais.","melhorias":"Ração aquecida: quem comer também recupera 1d4 Pontos de Vontade.","qtd":"3"},{"name":"Pílula de Vigília","tipo":"Consumível","pe":"0.5","acao":"Ação Bônus","mel":1,"desc":"Um estimulante que tira o sono. Por 12 horas, você não precisa dormir e ignora 1 nível de Estafa ou de exaustão. Quando o efeito acaba, você ganha 1 nível de exaustão.","melhorias":"Fórmula suave: você não ganha exaustão quando o efeito acaba, se dormir nas 6 horas seguintes.","qtd":"2"},{"name":"Munição de Borracha","tipo":"Consumível (Munição)","pe":"0.25","acao":"Ação","mel":1,"desc":"Um pente de munição não letal. Os disparos com ela causam dano contundente, e um alvo reduzido a 0 PV por ela cai inconsciente e estabilizado, em vez de começar os testes de vida ou morte.","melhorias":"Carga atordoante: num acerto crítico, o alvo também fica Atordoado até o fim do próximo turno dele.","qtd":"2"},{"name":"Munição de Ponta Oca","tipo":"Consumível (Munição)","pe":"0.5","acao":"Ação","mel":1,"desc":"Um pente de munição expansiva. Os disparos com ela causam +1 dado de dano contra alvos sem colete ou com colete leve, e −1 dado contra alvos com colete pesado.","melhorias":"Ponta controlada: a penalidade contra colete pesado deixa de existir.","qtd":"1"},{"name":"Cartucho Fléchette","tipo":"Consumível (Munição)","pe":"0.5","acao":"Ação","mel":1,"desc":"Cartuchos de shotgun com dardos de aço. Os disparos alcançam uma faixa a mais e ignoram 1 de CA vindo de colete, mas a shotgun não empurra o alvo.","melhorias":"Dardos farpados: um alvo atingido também perde 3m de Deslocamento até o fim do próximo turno dele.","qtd":"1"},{"name":"Cartucho Slug","tipo":"Consumível (Munição)","pe":"0.5","acao":"Ação","mel":1,"desc":"Cartuchos de shotgun de projétil único. A shotgun passa a usar o alcance Média e causa o dobro de dano em portas, fechaduras e coberturas.","melhorias":"Slug sabotado: a shotgun também ignora coberturas Leves.","qtd":"1"},{"name":"Célula de Energia","tipo":"Consumível","pe":"0.25","acao":"Ação","mel":1,"desc":"Uma bateria universal. Com uma Ação, você recupera 1 carga de um equipamento do tipo Bateria, ou alimenta um autômato ou Mecanizado como se fosse uma refeição.","melhorias":"Célula de alta capacidade: a célula recupera 2 cargas.","qtd":"3"},{"name":"Tinta de Camuflagem","tipo":"Consumível","pe":"0.25","acao":"Ação","mel":1,"desc":"Tinta para o rosto e as mãos. Por 8 horas, você tem Vantagem em Furtividade para se esconder no ambiente escolhido ao aplicar: mata, deserto, neve ou cidade.","melhorias":"Base térmica: a tinta também esconde o calor do seu rosto e mãos em visão térmica.","qtd":"3"},{"name":"Injetor de Reanimação \"CINZA\"","tipo":"Consumível","pe":"1.5","acao":"Ação","mel":2,"desc":"Uma pena de cinza estampada na seringa. Ninguém sabe quem desenhou primeiro.\nVocê aplica o injetor num aliado a até 1,5m que esteja com 0 PV. Ele volta na hora com 1d10 + Proef pontos de vida e pode se levantar sem gastar Deslocamento no próximo turno dele. Não funciona em quem já morreu.","melhorias":"Dose de fênix: o aliado também ganha 1d6 pontos de vida temporários.\nAplicador à distância: o injetor pode ser disparado num aliado a até 9m.","qtd":"1"},{"name":"Elixir de Combate","tipo":"Consumível","pe":"2.5","acao":"Ação","mel":1,"desc":"Caro, raro e guardado para o dia em que tudo der errado.\nVocê bebe o elixir ou aplica num aliado a até 1,5m. O alvo recupera metade dos pontos de vida máximos e todos os Pontos de Vontade, e cada equipamento de Bateria dele recupera 1 carga. Um operador só pode se beneficiar de um elixir por descanso longo.","melhorias":"Elixir puro: o alvo recupera todos os pontos de vida.","qtd":"1"},{"name":"Barraca de Campanha \"TENDA\"","tipo":"Consumível","pe":"1","acao":"Ação","mel":2,"desc":"Não é um hotel. Mas depois de três dias no mato, parece.\nUma barraca autoinflável com aquecimento, filtro de ar e iluminação baixa para até 6 pessoas. Um descanso curto feito dentro dela recupera todos os Pontos de Vontade de quem descansar, e cada um rola os dados de vida com Vantagem. Um descanso longo dentro dela também remove 1 nível de exaustão. A barraca se desmonta e se gasta depois do descanso.","melhorias":"Camuflagem: a barraca não aparece em visão térmica, e encontrá-la exige um teste de Percepção com Desvantagem.\nLona reforçada: a barraca pode ser usada duas vezes antes de se gastar.","qtd":"1"},{"name":"Granada Incendiária","tipo":"Lançável","pe":"1","acao":"Ação","mel":2,"desc":"Você arremessa a granada a até 12m. Ela explode num raio de 3m, e cada alvo na área faz um teste de resistência de Destreza (CD 10 + Proef + Des). Na falha, sofre 2d8 de dano incendiário e fica Queimado. No sucesso, sofre metade e não fica Queimado. A área continua em chamas por 1 minuto: quem entrar nela ou começar o turno nela sofre 1d6 de dano incendiário.","melhorias":"Gel aderente: apagar o fogo de um alvo Queimado por esta granada exige duas Ações em vez de uma.\nIgnição remota: você pode deixar a granada armada no chão e acender a área com uma Ação Bônus, a até 30m.","qtd":"2","excl":["Assalto"]},{"name":"Canister de Espuma \"Aegis\"","tipo":"Lançável","pe":"1","acao":"Ação","mel":2,"desc":"Você arremessa o canister a até 12m. Ao tocar o chão, ele cria uma barreira de espuma rígida de 2m de largura por 1,5m de altura, que conta como cobertura Média (30 PV). A espuma se desfaz depois de 1 minuto.","melhorias":"Ativação rápida: o arremesso passa a usar uma Ação Bônus.\nFórmula reforçada: a barreira conta como cobertura Pesada (60 PV).","qtd":"1","excl":["Assalto","Suporte"]},{"name":"Granada de Impacto","tipo":"Lançável","pe":"1","acao":"Ação","mel":2,"desc":"A granada explode ao tocar em qualquer coisa. Você arremessa a até 12m. Se mirar num alvo, faça um ataque à distância (Proef + Des): num acerto, ele sofre 3d6 de dano explosivo sem teste. A explosão também atinge um raio de 2m, e os outros alvos fazem um teste de resistência de Destreza (CD 10 + Proef + Des) para sofrer metade.","melhorias":"Carga perfurante: a explosão causa o dobro de dano em coberturas e portas.\nEstilhaços: o raio sobe para 3m.","qtd":"2","excl":["Assalto"]},{"name":"Semtex Adesiva","tipo":"Lançável","pe":"1.25","acao":"Ação","mel":2,"desc":"Faça um ataque à distância contra um alvo ou objeto a até 9m (Proef + Des). Num acerto, a granada gruda nele e explode no início do seu próximo turno: o alvo sofre 4d8 de dano explosivo sem teste, e quem estiver a até 2m faz um teste de resistência de Destreza (CD 10 + Proef + Des) para sofrer metade de 2d8. Antes disso, o alvo pode usar uma Ação para arrancar a granada com um teste de Força com a mesma CD.","melhorias":"Detonador remoto: você escolhe quando a granada explode, com uma Ação Bônus, a até 30m.\nPega-tudo: se o ataque errar, a granada gruda no chão ou parede ao lado do alvo e explode normalmente.","qtd":"1","excl":["Assalto"]},{"name":"Granada Termobárica","tipo":"Lançável","pe":"1.5","acao":"Ação","mel":1,"desc":"Você arremessa a granada a até 12m. Ela explode num raio de 4m, e cada alvo na área faz um teste de resistência de Destreza (CD 10 + Proef + Des). Na falha, sofre 3d10 de dano incendiário. No sucesso, sofre metade. Num ambiente fechado, como uma sala ou um túnel, a cobertura não protege contra ela, e os alvos na área ficam Surdos por 1 minuto.","melhorias":"Carga de vácuo: num ambiente fechado, os alvos que falharem também ficam Caídos.","qtd":"1","excl":["Assalto"]},{"name":"Granada em Cacho","tipo":"Lançável","pe":"1.5","acao":"Ação","mel":1,"desc":"Você arremessa a granada a até 15m. Ela se abre e espalha 3 submunições: escolha 3 pontos a até 6m de onde ela caiu. Cada ponto explode num raio de 2m, e cada alvo em uma área faz um teste de resistência de Destreza (CD 10 + Proef + Des) para sofrer metade de 2d6 de dano perfurante. Um alvo em mais de uma área sofre o dano de cada uma.","melhorias":"Quatro cargas: a granada espalha 4 submunições.","qtd":"1","excl":["Assalto"]},{"name":"Granada Gravitacional","tipo":"Lançável","pe":"1.5","acao":"Ação","mel":1,"desc":"Você arremessa a granada a até 12m. Ela cria um poço de gravidade num raio de 3m por um instante. Cada alvo na área faz um teste de resistência de Constituição (CD 10 + Proef + Des). Na falha, sofre dano igual a um quarto dos pontos de vida atuais dele, arredondado para baixo, com mínimo de 1d6, e fica Caído. No sucesso, sofre metade e não cai. Veículos e alvos marcados como chefe pelo mestre sofrem só o mínimo.","melhorias":"Colapso: os alvos que falharem também são puxados até o centro da área.","qtd":"1","excl":["Assalto","Hacker"]},{"name":"Cortina Tóxica","tipo":"Lançável","pe":"1","acao":"Ação","mel":2,"desc":"Você arremessa um tubo que se abre numa linha de gás de até 9m de comprimento e 3m de altura, que dura 1 minuto. A cortina bloqueia a linha de visão. Quem atravessar a cortina ou começar o turno dentro dela faz um teste de resistência de Constituição (CD 10 + Proef + Des). Na falha, sofre 2d6 de dano por veneno e fica Envenenado até o fim do próximo turno dele. Uma máscara de gás ou um traje Hazmat protege contra o efeito.","melhorias":"Gás corrosivo: quem falhar também perde 1 de CA do colete até o fim da cena.\nCortina dupla: você pode dobrar a linha em ângulo, com 9m em cada lado.","qtd":"1","excl":["Suporte","Cobra","Assalto"]},{"name":"Claymore","tipo":"Armadilha","pe":"1","acao":"Ação","mel":2,"desc":"Você posiciona a mina voltada para uma direção. Quando um alvo entrar a até 3m dela, ou quando você a acionar com uma Ação Bônus a até 30m, ela explode num cone de 6m. Cada alvo no cone faz um teste de resistência de Destreza (CD 10 + Proef + Des). Na falha, sofre 4d6 de dano perfurante. No sucesso, sofre metade.","melhorias":"Fio laser: o sensor vira um fio invisível, e notar a mina exige Percepção com Desvantagem.\nBlindagem anti-sabotagem: desarmar a mina exige um teste de Sabotagem com Desvantagem.","qtd":"1","excl":["Assalto","Franco-atirador"]},{"name":"C4 Explosiva","tipo":"Armadilha","pe":"1.5","acao":"Ação","mel":2,"desc":"Você gruda a carga numa superfície sólida. Com uma Ação Bônus, você detona a carga a até 300m. Ela explode num raio de 4m: cada alvo na área faz um teste de resistência de Destreza (CD 10 + Proef + Des) para sofrer metade de 4d10 de dano explosivo. Estruturas e veículos sofrem o dano total, e coberturas até Pesada na área são destruídas.","melhorias":"Temporizador: a carga pode explodir sozinha depois de 1 a 10 turnos, ou quando um alvo chegar a 1m dela.\nCarga moldada: a explosão vira um cone de 6m para um lado, e o dano sobe para 5d10 nesse cone.","qtd":"1","excl":["Assalto"]},{"name":"Carga de Brecha","tipo":"Armadilha","pe":"0.75","acao":"Ação","mel":1,"desc":"Uma carga em fita para portas e paredes finas. Você posiciona a carga e detona com uma Ação Bônus. Ela abre um buraco do tamanho de uma porta. Quem estiver a até 2m do outro lado faz um teste de resistência de Constituição (CD 10 + Proef + Des). Na falha, sofre 2d6 de dano explosivo e fica Atordoado até o fim do próximo turno dele.","melhorias":"Carga de parede: também abre paredes de alvenaria e portas blindadas leves.","qtd":"2","excl":["Assalto","Corpo-a-Corpo"]},{"name":"Mina Anti-veículo","tipo":"Armadilha","pe":"1.5","acao":"Ação","mel":1,"desc":"A mina só detona com um peso de 200kg ou mais. O veículo que passar sobre ela sofre 6d10 de dano explosivo e passa direto para o estado de Dano Grave se o dano for maior que metade da vida dele. Quem estiver a até 3m faz um teste de resistência de Destreza (CD 10 + Proef + Des) para sofrer metade de 3d10.","melhorias":"Carga penetrante: a explosão também atinge os ocupantes do veículo com metade do dano, sem teste.","qtd":"1","excl":["Assalto"]},{"name":"Mina Saltadora","tipo":"Armadilha","pe":"1.25","acao":"Ação","mel":1,"desc":"Quando um alvo pisar nela, a mina salta até a altura do peito e explode num raio de 4m. Cada alvo na área faz um teste de resistência de Destreza (CD 10 + Proef + Des). Na falha, sofre 3d8 de dano perfurante. No sucesso, sofre metade. Como a explosão vem de cima, cobertura parcial e de três quartos não ajudam no teste.","melhorias":"Atraso: a mina só salta depois que o alvo tirar o pé dela, o que dá tempo de mais alvos entrarem na área.","qtd":"1","excl":["Assalto"]},{"name":"Linha de Napalm","tipo":"Armadilha","pe":"1.25","acao":"Ação","mel":1,"desc":"Você estica uma mangueira de napalm de até 9m no chão. Com uma Ação Bônus, a até 30m, você acende a linha e ela vira uma parede de fogo de 3m de altura por 1 minuto. Quem estiver sobre a linha quando ela acender, ou atravessá-la, faz um teste de resistência de Destreza (CD 10 + Proef + Des). Na falha, sofre 3d6 de dano incendiário e fica Queimado. No sucesso, sofre metade. A parede bloqueia a linha de visão.","melhorias":"Linha em curva: você pode montar a linha em círculo, com até 6m de diâmetro.","qtd":"1","excl":["Assalto"]},{"name":"Mina Buscadora","tipo":"Armadilha","pe":"1.25","acao":"Ação","mel":2,"desc":"Você solta a mina no chão e escolhe um alvo que possa ver. Ela rola atrás dele a até 12m por turno, no início de cada um dos seus turnos, durante 1 minuto. Quando chegar a até 1,5m do alvo, explode num raio de 2m: cada alvo na área faz um teste de resistência de Destreza (CD 10 + Proef + Des) para sofrer metade de 3d8 de dano explosivo. A mina tem CA 13 e 5 PV e pode ser destruída antes.","melhorias":"Enxame: a mina se divide em 3 minas menores, cada uma atrás de um alvo diferente, causando 2d6 cada.\nCarga de gás: em vez de explodir, a mina solta uma nuvem de gás lacrimogêneo de 3m.","qtd":"2","excl":["Assalto","Hacker"]},{"name":"Escudo de Energia \"Aegis-X\"","tipo":"Bateria","pe":"1.5","acao":"Ação Bônus","mel":2,"desc":"Um gerador de campo preso ao braço. Ligado, ele cria um campo de 1m à sua frente que reduz pela metade o dano de ataques à distância vindos da frente. O campo tem 30 PV e se desliga quando eles acabam, voltando cheio depois de 1 minuto desligado.","melhorias":"Campo expansivo: o campo tem 2m e protege também um aliado ao seu lado.\nBlindagem contra explosões: o campo também reduz pela metade o dano de explosões vindas da frente.","excl":["Assalto"]},{"name":"Baluarte de Pulso","tipo":"Bateria","pe":"2","acao":"Reação","mel":2,"desc":"Quando um inimigo chegar a até 2m de você, ou uma granada cair a até 2m, use a Reação e gaste uma carga para soltar uma onda de choque à sua frente. Os inimigos na área fazem um teste de resistência de Força (CD 10 + Proef + Int). Na falha, são empurrados 3m. Granadas na área são jogadas para fora antes de explodir.","melhorias":"Pulso concentrado: quem falhar também fica Caído.\nDissipação magnética: o pulso também desliga drones e armadilhas eletrônicas na área até o fim do seu próximo turno.","cargas":"3","excl":["Assalto","Corpo-a-Corpo"]},{"name":"Sistema de Defesa Ativa (ADS)","tipo":"Bateria","pe":"1.5","acao":"Ação","mel":1,"desc":"Você posiciona o ADS num ponto a até 1,5m. Até ele ser recolhido ou destruído, quando uma granada, foguete ou projétil de lançador entrar num raio de 4m dele, o ADS gasta uma carga e destrói o projétil antes da explosão. Ele tem CA 14 e 15 PV.","melhorias":"Rastreio rápido: o raio sobe para 6m.","cargas":"3","excl":["Assalto"]},{"name":"Emissor de Campo Reativo","tipo":"Bateria","pe":"1.25","acao":"Ação Livre","mel":2,"desc":"Gaste uma carga para ligar o campo por 2 turnos. Enquanto ele estiver ligado, todo dano que você sofrer é reduzido em 2, e quem acertar você com um ataque corpo a corpo sofre 1d4 de dano elétrico.","melhorias":"Campo forte: a redução sobe para 3.\nDescarga: o dano de retorno sobe para 1d8.","cargas":"2","excl":["Corpo-a-Corpo","Assalto"]},{"name":"Cobertura Móvel T-60 \"Bastion\"","tipo":"Bateria","pe":"1","acao":"Ação","mel":2,"desc":"Um painel dobrável motorizado. Com uma Ação, você abre o painel num ponto a até 1,5m: ele vira uma cobertura Média de 1,5m de largura (30 PV) contra ataques da frente. Uma vez por turno, você pode mover o painel 3m com o seu Deslocamento, ficando atrás dele.","melhorias":"Placa reforçada: o painel conta como cobertura Pesada (60 PV).\nVisor de tiro: quem atira de trás do painel não perde a cobertura ao atacar.","excl":["Assalto"]},{"name":"\"SWARM\" Microfoguetes Guiados","tipo":"Bateria","pe":"1.5","acao":"Ação","mel":2,"desc":"Gaste uma carga para disparar 3 microfoguetes a até 36m. Cada um acerta automaticamente um alvo que você possa ver, causando 1d4 + 1 de dano explosivo. Você pode mandar todos no mesmo alvo ou dividir entre alvos diferentes.","melhorias":"Quatro foguetes: cada carga dispara 4 microfoguetes.\nOgiva perfurante: os foguetes causam o dobro de dano em drones e veículos.","cargas":"2","excl":["Assalto","Hacker"]},{"name":"\"CERBERUS\" Sistema Autônomo de Interceptação","tipo":"Bateria","pe":"2.5","acao":"Reação","mel":2,"desc":"Três microdrones orbitam o operador e derrubam ameaças antes que cheguem até ele.\nOs três drones ficam orbitando você. Use a Reação e gaste uma carga quando uma destas situações acontecer: uma granada cai a até 3m de você, um foguete ou míssil vai atingir você, ou um disparo de rifle de precisão ou rifle antimaterial vai acertar você. Um drone intercepta a ameaça e anula os efeitos dela contra você. A granada ou foguete ainda explode no lugar onde foi interceptado, e afeta quem estiver lá.","melhorias":"Escolta: o sistema também pode proteger um aliado a até 3m de você.\nQuarto drone: o sistema tem 4 cargas.","cargas":"3","excl":["Assalto"]},{"name":"Emissor de Provocação \"ISCA\"","tipo":"Bateria","pe":"1.5","acao":"Ação Bônus","mel":2,"desc":"Alguém tem que segurar a linha. Que seja quem aguenta.\nGaste uma carga para ligar o emissor por 1 minuto. Ele faz barulho, pisca e emite um sinal que chama atenção. Cada inimigo a até 9m de você faz um teste de resistência de Sabedoria (CD 10 + Proef + Con) no início do turno dele. Na falha, ele tem Desvantagem nos ataques contra qualquer alvo que não seja você até o início do próximo turno dele.","melhorias":"Placa de impacto: enquanto o emissor estiver ligado, você reduz em 2 todo dano de armas que sofrer.\nSinal forte: o raio sobe para 15m.","cargas":"2","excl":["Assalto","Suporte","Corpo-a-Corpo"]},{"name":"Robô Bloqueador","tipo":"Bateria","pe":"2","acao":"Ação","mel":2,"desc":"Um robô blindado e baixo que fica parado num ponto a até 1,5m e segura a posição. Ele conta como cobertura Média para quem estiver atrás dele, e um inimigo que começar o turno a até 1,5m do robô não pode passar pelo espaço dele nem se afastar mais de metade do Deslocamento sem antes fazer um teste de Força (CD 10 + Proef + Int). O robô tem CA 16 e 30 PV e não ataca.","melhorias":"Escudo frontal: o robô conta como cobertura Pesada.\nReparo rápido: com uma Ação, você restaura 1d8 + Int PV do robô.","excl":["Assalto","Comando"]},{"name":"Morteiro Portátil","tipo":"Bateria","pe":"2.5","acao":"Ação","mel":2,"desc":"Um tubo de morteiro leve que você monta em 1 minuto. Montado, você gasta uma carga para disparar contra um ponto a até 500m que você ou um aliado consiga ver, sem precisar de linha de visão. O disparo cai no início do seu próximo turno num raio de 4m. Cada alvo na área faz um teste de resistência de Destreza (CD 10 + Proef + Int) para sofrer metade de 3d8 de dano explosivo. Cobertura não protege, porque o disparo vem de cima.","melhorias":"Granada de fumaça: em vez de explosivo, o disparo pode soltar fumaça num raio de 8m.\nMontagem rápida: montar o morteiro leva uma Ação.","cargas":"3","excl":["Assalto","Comando"]},{"name":"Máscara de Kevlar","tipo":"Vestido","pe":"0.75","acao":"Ação Livre","mel":2,"desc":"Máscara balística que protege o rosto. Um acerto crítico contra você que caia na Cabeça vira um acerto normal uma vez por descanso curto.","melhorias":"Visor reforçado: você tem Vantagem nos testes de resistência contra Granadas de Luz.\nAparência ameaçadora: você tem Vantagem no primeiro teste de Intimidação de cada cena.","excl":["Assalto","Corpo-a-Corpo"]},{"name":"\"BULLRUSH\" Exoesqueleto de Impulso","tipo":"Vestido","pe":"2","acao":"Ação Bônus","mel":2,"desc":"Um exoesqueleto leve com pistões. Com uma Ação Bônus, você investe até 6m em linha reta, atravessando terreno difícil e obstáculos baixos. Se terminar ao lado de um inimigo, ele faz um teste de resistência de Constituição (CD 10 + Proef + For). Na falha, fica Caído. Você também reduz em 2 o dano de quedas e de ataques contundentes.","melhorias":"Carga devastadora: a investida também causa 2d6 de dano contundente ao inimigo.\nPistões de salto: você salta até 5m de altura sem teste.","excl":["Assalto","Corpo-a-Corpo"]},{"name":"Bolsa de Reabastecimento Tático","tipo":"Vestido","pe":"1","acao":"Ação Bônus","mel":1,"desc":"Uma bolsa de munição universal presa ao cinto. Gaste uma carga para repor 1 pente da sua arma primária ou 2 pentes da secundária. Com uma Ação, você pode gastar a carga num aliado a até 1,5m.","melhorias":"Bolsa grande: a bolsa tem 5 cargas.","cargas":"3","excl":["Assalto","Comando"]},{"name":"Traje Ignífugo","tipo":"Vestido","pe":"0.75","acao":"Ação","mel":1,"desc":"Roupa de bombeiro adaptada para o combate. Você tem resistência a dano incendiário e não fica Queimado. Entrar em áreas em chamas não causa dano a você no primeiro turno.","melhorias":"Capuz térmico: você também é invisível para visão térmica enquanto estiver numa área em chamas.","excl":["Assalto","Suporte"]},{"name":"Exoesqueleto Logístico","tipo":"Vestido","pe":"1.5","acao":"Ação","mel":1,"desc":"Um exoesqueleto de carga, feito para mover munição e equipamento. A sua Carga máxima sobe 6, e você carrega uma arma pesada, como uma LMG ou um lançador, sem a penalidade de Deslocamento dela.","melhorias":"Braço auxiliar: você pode ter a arma primária e uma arma pesada em mãos ao mesmo tempo, sem Troca entre elas.","excl":["Assalto"]},{"name":"\"ARES\" Exoesqueleto de Combate Assistido","tipo":"Vestido / Bateria","pe":"3","acao":"Ação Livre","mel":2,"desc":"Atuadores hidráulicos e músculos artificiais que amplificam cada movimento por alguns segundos.\nUma vez por turno, gaste uma carga para ativar o exoesqueleto por 3 turnos. Enquanto ele estiver ativo, você recebe +3m de Deslocamento e +2 de CA, ignora terreno difícil, troca de arma e saca ou guarda equipamentos sem teste de Troca e sem gastar Ação, e tem Vantagem em testes de Força. Quando o efeito acaba, o exoesqueleto superaquece: você tem −3m de Deslocamento até o fim do seu próximo turno.","melhorias":"Refrigeração líquida: o exoesqueleto não superaquece quando o efeito acaba.\nServos de carga: enquanto ativo, você carrega uma arma pesada sem a penalidade de Deslocamento dela.","cargas":"2","excl":["Assalto"]},{"name":"Medidor de Limite \"LIMIT\"","tipo":"Vestido","pe":"1.5","acao":"Ação Livre","mel":2,"desc":"Um medidor no braço que enche com a dor. Quando chega no topo, alguma coisa explode.\nUm bracelete com sensores de adrenalina. Você ganha 1 marca de limite quando cai para menos da metade dos seus PV, quando um aliado cai a 0 PV à sua vista e quando sofre um acerto crítico. O máximo é 3 marcas. Com 3 marcas, use uma Ação Livre para liberar o limite: até o fim do seu turno, os seus ataques causam o dano máximo dos dados, sem rolar. As marcas zeram depois de liberar ou num descanso longo.","melhorias":"Limite rápido: você ganha 1 marca também quando reduz um inimigo a 0 PV.\nLimite compartilhado: ao liberar, um aliado a até 9m também causa o dano máximo dos dados no próximo ataque dele.","excl":["Corpo-a-Corpo","Assalto"]},{"name":"Colete de Descarga \"TUFÃO\"","tipo":"Vestido / Bateria","pe":"2","acao":"Ação","mel":2,"desc":"Um colete com cargas explosivas direcionais. Gaste uma carga para soltar uma explosão em volta de você. Cada inimigo a até 3m faz um teste de resistência de Destreza (CD 10 + Proef + Con). Na falha, sofre 3d8 de dano explosivo. No sucesso, sofre metade. As cargas são direcionais, então você e os aliados na área não são atingidos.","melhorias":"Estilhaços: o raio sobe para 5m.\nRecarga em campo: você recupera 1 carga num descanso curto.","cargas":"2","excl":["Corpo-a-Corpo","Assalto"]},{"name":"Mochila a Jato","tipo":"Vestido / Bateria","pe":"2.5","acao":"Ação Bônus","mel":2,"desc":"Gaste uma carga para ligar a mochila por 3 turnos. Enquanto ela estiver ligada, você voa com o seu Deslocamento e pode pairar no ar. Se o efeito acabar com você no ar, você desce devagar e pousa sem dano. O barulho do motor dá Desvantagem em Furtividade.","melhorias":"Turbina silenciosa: a mochila não dá mais Desvantagem em Furtividade.\nCombustível extra: a mochila voa por 5 turnos por carga.","cargas":"2","excl":["Assalto","Franco-atirador"]},{"name":"Bracelete de Carga Cinética","tipo":"Vestido","pe":"2","acao":"Ação Livre","mel":2,"desc":"Quanto mais tempo a lâmina espera, mais fundo ela corta.\nUm bracelete que acumula a energia dos seus movimentos. No fim de cada turno em que você não atacar, ganha 1 marca de carga, até 3. No primeiro acerto corpo a corpo que você fizer depois, gasta todas as marcas: o ataque causa +1d10 de dano por marca, e o alvo faz um teste de resistência de Força (CD 10 + Proef + For) para não ser empurrado 1,5m por marca. As marcas somem num descanso curto.","melhorias":"Bobina extra: o máximo sobe para 4 marcas.\nContenção: receber dano não impede o acúmulo, e você ganha 1 marca também quando um ataque corpo a corpo erra você.","excl":["Corpo-a-Corpo","Assalto"]},{"name":"Munição Explosiva M-E9 \"Breaker\"","tipo":"Consumível (Munição)","pe":"0.5","acao":"Ação","mel":2,"desc":"Um projétil explosivo para lançadores acoplados. Você dispara a até 20m, e ele explode num raio de 2m. Cada alvo na área faz um teste de resistência de Destreza (CD 10 + Proef + Des) para sofrer metade de 2d10 de dano explosivo. Portas, barricadas e paredes finas no ponto de impacto são destruídas.","melhorias":"Carga penetrante: o projétil atravessa uma parede fina e explode do outro lado.\nPropulsor estendido: o alcance sobe para 30m.","qtd":"2","excl":["Assalto"]},{"name":"M-G12 \"Masterkey\"","tipo":"Consumível (Munição)","pe":"1","acao":"Ação Livre","mel":2,"desc":"Uma escopeta de um cartucho acoplada sob o cano da arma primária. Uma vez por turno, você dispara a até 5m num cone de 2m. Cada alvo no cone faz um teste de resistência de Destreza (CD 10 + Proef + Des) para sofrer metade de 2d8 de dano perfurante. Portas de madeira e barricadas leves no cone são destruídas.","melhorias":"Carregador alternativo: a quantidade sobe para 2.\nCartucho de concussão: em vez de dano, quem falhar no teste fica Atordoado até o fim do próximo turno dele.","qtd":"1","excl":["Assalto","Corpo-a-Corpo"]},{"name":"Munição Incendiária","tipo":"Consumível (Munição)","pe":"0.75","acao":"Ação","mel":1,"desc":"Um pente de munição incendiária. Os disparos com ela causam dano incendiário, e um alvo atingido faz um teste de resistência de Destreza (CD 10 + Proef + Des). Na falha, fica Queimado.","melhorias":"Fósforo: o alvo Queimado por esta munição precisa de duas Ações para apagar o fogo.","qtd":"1","excl":["Assalto"]},{"name":"Munição Perfurante","tipo":"Consumível (Munição)","pe":"0.75","acao":"Ação","mel":1,"desc":"Um pente de munição de núcleo duro. Os disparos com ela ignoram 2 de CA vindos de colete e atravessam coberturas Leves.","melhorias":"Núcleo de tungstênio: os disparos também atravessam coberturas Médias.","qtd":"1","excl":["Franco-atirador","Assalto"]},{"name":"Cartucho \"Dragon's Breath\"","tipo":"Consumível (Munição)","pe":"0.75","acao":"Ação","mel":1,"desc":"Cartuchos de shotgun com magnésio incendiário. O disparo vira um cone de fogo de 5m, e cada alvo no cone faz um teste de resistência de Destreza (CD 10 + Proef + Des) para sofrer metade do dano da arma como dano incendiário. Quem falhar fica Queimado.","melhorias":"Carga longa: o cone chega a 8m.","qtd":"1","excl":["Assalto"]},{"name":"Pacote de Blindagem \"Bastião\"","tipo":"Consumível","pe":"1.5","acao":"Ação","mel":1,"desc":"Uma bolsa pesada com 5 placas balísticas. Você larga a bolsa no chão, e qualquer aliado ao lado dela pode usar uma Ação Bônus para encaixar uma placa no colete. A placa dá +1 de CA. Na primeira vez que esse aliado for reduzido a 0 PV por um ataque, a placa se parte e ele fica com 1 PV.","melhorias":"Placas leves: encaixar a placa não gasta Ação Bônus de quem estiver ao lado da bolsa no início do turno.","qtd":"5","excl":["Suporte","Assalto"]},{"name":"Injetor \"FÚRIA\"","tipo":"Consumível","pe":"1","acao":"Ação Bônus","mel":2,"desc":"Remove o medo, a dor e boa parte do bom senso.\nVocê aplica o injetor em você. Por 1 minuto, você tem Vantagem nas jogadas de ataque corpo a corpo e +1d6 de dano nos acertos, e é imune a Amedrontado. Enquanto o efeito durar, você só pode atacar ou se mover em direção ao inimigo mais próximo, e os ataques contra você têm Vantagem. Quando o efeito acaba, você perde 2d6 Pontos de Vontade.","melhorias":"Fúria controlada: você pode encerrar o efeito com uma Ação Livre.\nDose de choque: o dano extra sobe para +1d8.","qtd":"1","excl":["Corpo-a-Corpo","Assalto"]},{"name":"Munição Antiaérea","tipo":"Consumível (Munição)","pe":"0.75","acao":"Ação","mel":1,"desc":"Primeiro o que voa. Depois o resto.\nUm pente de munição com espoleta de proximidade, feita para alvos no ar. Os disparos com ela recebem +2 de Precisão contra drones, aeronaves e alvos voando, e causam +1 dado de dano contra eles. Um drone atingido também faz um teste de Constituição (CD 10 + Proef + Des) para não cair e ficar desativado até o fim do seu próximo turno.","melhorias":"Estilhaços aéreos: um disparo contra um alvo voando também atinge outro alvo voando a até 3m dele, com metade do dano.","qtd":"1","excl":["Franco-atirador","Assalto"]},{"name":"Granada Sensor","tipo":"Lançável","pe":"1","acao":"Ação Bônus","mel":2,"desc":"Você arremessa o disco a até 12m, e ele gruda onde cair. Por 1 minuto, ele mostra a você e aos aliados com pontos pareados a posição de todo alvo a até 6m dele, inclusive através de paredes finas, fumaça e escuridão. Esses alvos não podem ficar Escondidos contra vocês.","melhorias":"Telemetria: os seus aliados recebem +1 de Precisão contra os alvos revelados pelo disco.\nBateria estendida: o disco funciona por 10 minutos.","qtd":"2","excl":["Franco-atirador","Comando","Hacker"]},{"name":"Lâmina de Pulso","tipo":"Lançável","pe":"1","acao":"Ação Bônus","mel":2,"desc":"Uma faca com um emissor de sonar no cabo. Você arremessa a até 12m, e ela se crava numa superfície. No início de cada um dos seus próximos 3 turnos, ela solta um pulso que revela a você e aos seus aliados a posição de todo inimigo a até 9m dela, inclusive através de paredes, até o fim daquele turno. Se acertar um alvo com um ataque à distância (Proef + Des), causa 1d6 + Des de dano perfurante e fica presa nele, revelando a posição dele pelos 3 turnos.","melhorias":"Pulso extra: a lâmina solta 5 pulsos em vez de 3.\nRecuperável: depois dos pulsos, a lâmina pode ser recuperada e não se gasta.","qtd":"2","excl":["Franco-atirador","Corpo-a-Corpo"]},{"name":"Drone Cegante","tipo":"Lançável","pe":"1","acao":"Ação Bônus","mel":1,"desc":"Você solta um drone pequeno que voa até 18m numa direção. No fim do voo, ou quando chegar a 3m de um inimigo, ele explode num clarão. Cada alvo a até 6m que estiver olhando para o drone faz um teste de resistência de Constituição (CD 10 + Proef + Des). Na falha, fica Cego até o fim do próximo turno dele. O drone faz curvas, então você pode mandá-lo por trás de uma cobertura.","melhorias":"Guiado: você controla o drone durante o voo e escolhe o momento da explosão.","qtd":"2","excl":["Franco-atirador","Comando"]},{"name":"Boneco Inflável","tipo":"Lançável","pe":"0.5","acao":"Ação","mel":2,"desc":"Ninguém resiste a atirar num soldado parado.\nVocê infla um boneco com a forma de um soldado num ponto a até 6m. Visto de longe, ele parece uma pessoa. Os inimigos que o virem a mais de 9m acreditam que é real até chegarem perto ou passarem num teste de Investigação (CD 12 + Proef + Des). O boneco atrai tiros: até ser destruído, inimigos que não sabem que é falso o tratam como alvo. Ele tem CA 10 e 5 PV.","melhorias":"Assinatura térmica: o boneco também engana visão térmica.\nBoneco armado: o boneco carrega uma granada de luz que explode quando ele é destruído.","qtd":"2","excl":["Cobra","Franco-atirador"]},{"name":"Armadilha de Laço","tipo":"Armadilha","pe":"0.25","acao":"Ação","mel":1,"desc":"Você monta um laço camuflado no chão. O primeiro alvo que pisar nele faz um teste de resistência de Destreza (CD 12 + Proef + Des). Na falha, fica pendurado de cabeça para baixo e Impedido. Para se soltar, usa uma Ação e faz um teste de Força ou Acrobacia com a mesma CD.","melhorias":"Cabo de aço: o laço só pode ser cortado com uma arma cortante ou ferramenta.","qtd":"2","excl":["Franco-atirador"]},{"name":"Rede de Teto","tipo":"Armadilha","pe":"0.75","acao":"Ação","mel":1,"desc":"Você prende a rede no teto ou numa árvore sobre uma área de 3m por 3m e liga a um gatilho de pressão ou a um disparo remoto. Quando ela cair, cada alvo na área faz um teste de resistência de Destreza (CD 10 + Proef + Des). Na falha, fica Impedido até se soltar, com uma Ação e um teste de Força com a mesma CD.","melhorias":"Pesos de chumbo: quem falhar também fica Caído.","qtd":"1","excl":["Franco-atirador"]},{"name":"Drone de Reconhecimento","tipo":"Bateria","pe":"1.5","acao":"Ação Bônus","mel":2,"desc":"Um drone silencioso que voa até 25m de você por até 1 hora. Com uma Ação Bônus, você move o drone até 12m e vê pela câmera dele, com visão noturna. O drone tem CA 13 e 10 PV e faz testes de Furtividade com o seu bônus.","melhorias":"Marcador de alvos: com uma Ação Bônus, o drone marca um alvo, e os ataques à distância contra ele recebem +1 de Precisão até o fim do seu próximo turno.\nModo automático: o drone segue uma rota programada por até 3 turnos sem precisar de você.","excl":["Franco-atirador","Hacker"]},{"name":"\"EYE-X\" Câmeras de Vigilância","tipo":"Bateria","pe":"1.5","acao":"Ação Bônus","mel":2,"desc":"Gaste uma carga para arremessar uma microcâmera a até 6m. Ela gruda em qualquer superfície e transmite vídeo para você até ser destruída ou recolhida. Você troca de câmera com uma Ação Bônus. Notar uma câmera exige um teste de Percepção (CD 12 + Proef + Int).","melhorias":"Transmissão térmica: as câmeras também têm visão térmica.\nMicro P.E.M.: com uma Ação, você explode uma câmera num pulso de 3m que desliga eletrônicos até o fim do seu próximo turno.","cargas":"3","excl":["Cobra","Hacker","Franco-atirador"]},{"name":"Marcador Tático \"Olho-Certo\"","tipo":"Bateria","pe":"1","acao":"Ação Bônus","mel":2,"desc":"Gaste uma carga para arremessar um disco a até 10m. Por 3 turnos, ele cria uma zona com raio de 6m: você e os seus aliados recebem +1 de Precisão contra inimigos dentro dela.","melhorias":"Análise de ponto fraco: o bônus sobe para +2.\nScan de cobertura: os inimigos na zona não recebem o bônus de cobertura parcial.","cargas":"2","excl":["Franco-atirador","Comando"]},{"name":"Radar de Pulso Portátil","tipo":"Bateria","pe":"1.5","acao":"Ação","mel":1,"desc":"Gaste uma carga para soltar um pulso com raio de 20m. Você descobre a posição de todo alvo em movimento na área naquele momento, inclusive atrás de paredes. Quem estiver parado e Escondido não aparece.","melhorias":"Pulso fino: o radar também mostra alvos parados que estejam respirando ou com motor ligado.","cargas":"3","excl":["Franco-atirador","Comando"]},{"name":"Drone de Sincronia","tipo":"Bateria","pe":"2","acao":"Ação Bônus","mel":2,"desc":"Quatro alvos, quatro gatilhos, um disparo.\nGaste uma carga para lançar o drone, que marca até 4 alvos que você e os seus aliados consigam ver. Até o fim do seu próximo turno, quando você atacar um alvo marcado, cada aliado que tenha um alvo marcado na linha de visão pode usar a Reação para fazer um disparo contra ele ao mesmo tempo. Esses disparos sofrem Recuo normalmente para quem já tiver disparado no turno.","melhorias":"Mira assistida: os disparos sincronizados recebem +1 de Precisão.\nMarcação longa: as marcas duram até o fim do seu segundo turno seguinte.","cargas":"2","excl":["Franco-atirador","Comando"]},{"name":"Escâner de Análise \"LIBRA\"","tipo":"Bateria","pe":"1","acao":"Ação Bônus","mel":2,"desc":"Você aponta o escâner para um alvo que possa ver a até 30m. Descobre os pontos de vida atuais e máximos, a CA, as resistências, as vulnerabilidades e um traço ou habilidade dele, à escolha do mestre.","melhorias":"Leitura completa: você também descobre os estados que afetam o alvo e o equipamento que ele carrega.\nCompartilhar: os aliados com pontos pareados recebem a mesma informação.","excl":["Comando","Hacker","Franco-atirador"]},{"name":"Cão Tático","tipo":"Bateria","pe":"2","acao":"Ação Bônus","mel":2,"desc":"Leal, silencioso e com um faro melhor que qualquer sensor.\nUm cão treinado com colete e câmera. Ele obedece a comandos com uma Ação Bônus: farejar (você tem Vantagem para rastrear e para achar explosivos e pessoas escondidas a até 9m dele), vigiar (ele avisa quando alguém chega a até 18m) ou atacar (ele faz um ataque com Precisão igual à sua Proef + Sab, causando 1d8 + 2 de dano perfurante, e o alvo faz um teste de Força, CD 10 + Proef + Sab, para não ficar Caído). O cão tem CA 13, 20 PV e Deslocamento de 12m. Se ele cair a 0 PV, precisa ser tratado com Medicina. Cuidar dele exige um teste de Adestrar Animais por descanso longo, a critério do mestre.","melhorias":"Colete balístico: o cão tem CA 15.\nTreino avançado: o ataque do cão causa 1d10 + 2 de dano.","excl":["Franco-atirador","Comando"]},{"name":"Uplink Satelital","tipo":"Bateria","pe":"2","acao":"Ação","mel":2,"desc":"Uma antena dobrável que conecta você a um satélite de observação. Montar leva 1 minuto ao ar livre. Gaste uma carga para observar de cima uma área de até 1km por 10 minutos: você vê veículos, grupos de pessoas, construções e movimentos ao ar livre, como num mapa ao vivo, e pode passar o que vê para os aliados com pontos pareados. O satélite não vê dentro de prédios nem através de nuvens densas.","melhorias":"Modo térmico: o satélite também mostra assinaturas de calor, inclusive de pessoas embaixo de árvores.\nMarcação: os alvos que você marcar no mapa aparecem para os aliados por 1 hora.","cargas":"2","excl":["Hacker","Comando","Franco-atirador"]},{"name":"\"GHOSTWEAVE\" Manto Óptico","tipo":"Vestido / Bateria","pe":"1","acao":"Ação Bônus","mel":2,"desc":"Um manto de tecido óptico que copia as cores do ambiente. Gaste uma carga para ligar a camuflagem por 5 turnos: você recebe +3 em Furtividade, e câmeras e sensores ópticos têm Desvantagem para localizar você.","melhorias":"Desvio óptico: uma vez por combate, quando um ataque for feito contra você, use a Reação para impor Desvantagem a ele.\nSilenciador de movimento: enquanto a camuflagem estiver ligada, você se move na velocidade normal sem penalidade em Furtividade.","cargas":"2","excl":["Cobra","Franco-atirador"]},{"name":"Botas de Infiltração","tipo":"Vestido","pe":"0.5","acao":"Ação Livre","mel":1,"desc":"Botas de solado macio que abafam os passos. Você tem Vantagem em Furtividade para não ser ouvido, e não deixa pegadas em chão duro.","melhorias":"Solado aderente: você escala superfícies ásperas e anda em telhados inclinados sem teste.","excl":["Cobra","Franco-atirador"]},{"name":"Óculos Trifocais","tipo":"Vestido / Bateria","pe":"1.5","acao":"Ação Bônus","mel":2,"desc":"Três lentes verdes no escuro, e o guarda nunca soube de onde veio.\nÓculos com três modos, trocados com uma Ação Bônus: visão noturna (enxerga no escuro até 30m), térmica (vê calor através de fumaça e de cobertura Leve) e eletromagnética (vê fios, câmeras, lasers e aparelhos ligados através de paredes até 15m). Gaste uma carga para soltar um pulso de sonar: você descobre a posição de todos os alvos a até 15m, inclusive atrás de paredes, até o fim do seu turno.","melhorias":"Lentes rápidas: trocar de modo não gasta Ação.\nSonar silencioso: o pulso de sonar não pode ser percebido por quem está na área.","cargas":"3","excl":["Cobra","Franco-atirador"]},{"name":"Botas de Levitação \"FLUTUAR\"","tipo":"Vestido / Bateria","pe":"1","acao":"Ação Bônus","mel":2,"desc":"Gaste uma carga para ligar as botas por 1 minuto. Você flutua a meio metro do chão: não ativa minas, placas de pressão nem armadilhas de chão, ignora estrepes, terreno difícil, gelo e água rasa, e não é afetado por ondas de choque que corram pelo chão. Você não sofre dano de quedas enquanto elas estiverem ligadas.","melhorias":"Planador: enquanto as botas estiverem ligadas, você pode atravessar vãos de até 6m flutuando.\nBateria longa: as botas duram 10 minutos por carga.","cargas":"2","excl":["Cobra","Franco-atirador"]},{"name":"Traje Ghillie","tipo":"Vestido","pe":"1","acao":"Ação","mel":2,"desc":"Um arbusto que respira e tem uma DMR.\nUm traje de camuflagem coberto de tiras de pano e vegetação do lugar. Vestir leva 10 minutos. Em mata, campo ou neve, você tem Vantagem em Furtividade e pode ficar Escondido mesmo sem cobertura, desde que não se mova mais de 3m no turno. Disparar não revela a sua posição para quem estiver a mais de 30m, se você tiver um Supressor.","melhorias":"Malha térmica: o traje também esconde você de visão térmica.\nGhillie urbano: o traje funciona também em escombros e ruínas.","excl":["Franco-atirador"]},{"name":"Munição Marcadora","tipo":"Consumível (Munição)","pe":"1","acao":"Ação","mel":1,"desc":"Um pente de munição com marcadores. Um alvo atingido por um disparo com esta munição fica marcado por 3 turnos: você e os seus aliados recebem +2 de Precisão contra ele.","melhorias":"Marcação acirrada: os disparos contra o alvo marcado também causam +2 de dano.","qtd":"1","excl":["Franco-atirador"]},{"name":"Munição Subsônica","tipo":"Consumível (Munição)","pe":"0.5","acao":"Ação","mel":1,"desc":"Um pente de munição lenta e silenciosa. Com um Supressor, os disparos não fazem barulho nenhum, e você não perde o estado Escondido ao atacar se o disparo derrubar o alvo. O alcance da arma cai uma faixa.","melhorias":"Carga balanceada: o alcance da arma não cai.","qtd":"1","excl":["Cobra","Franco-atirador"]},{"name":"Spray de Camuflagem Térmica","tipo":"Consumível","pe":"0.75","acao":"Ação","mel":1,"desc":"Um gel que bloqueia o calor do corpo. Por 10 minutos, você é invisível para visão térmica e sensores de calor.","melhorias":"Lata grande: o spray cobre você e um aliado ao mesmo tempo.","qtd":"2","excl":["Cobra","Franco-atirador"]},{"name":"Pó de Rastreamento","tipo":"Consumível","pe":"0.5","acao":"Ação","mel":1,"desc":"Nanopartículas que grudam em roupas, pneus e pele. Você espalha o pó numa área de 3m ou num objeto, e qualquer pessoa ou veículo que passar por ela carrega as partículas por 48 horas. Os seus equipamentos mostram a posição de quem carrega o pó a até 5km.","melhorias":"Pó invisível: notar o pó exige um teste de Investigação com Desvantagem, mesmo com luz UV.","qtd":"2","excl":["Cobra","Franco-atirador"]},{"name":"Dardo Rastreador","tipo":"Consumível (Munição)","pe":"0.5","acao":"Ação","mel":1,"desc":"Um projétil com um transmissor que você dispara de uma arma longa. Faça um disparo normal contra um alvo: num acerto, em vez de causar dano, o dardo se crava nele sem que ele perceba, a menos que passe num teste de Percepção (CD 12 + Proef + Des). Por 24 horas, você sabe a posição do alvo a até 10km.","melhorias":"Escuta: o dardo também transmite o que for dito a até 3m do alvo.","qtd":"2","excl":["Franco-atirador","Cobra"]},{"name":"Granada Sedativa","tipo":"Lançável","pe":"1.25","acao":"Ação","mel":1,"desc":"Você arremessa a granada a até 12m. Ela solta um gás sonífero com raio de 3m que dura 1 minuto. Quem entrar na nuvem ou começar o turno nela faz um teste de resistência de Constituição (CD 10 + Proef + Des). Na falha, fica Envenenado e com o Deslocamento pela metade. Quem falhar por 5 ou mais, ou falhar estando fora de combate, cai Inconsciente por 1 minuto ou até sofrer dano.","melhorias":"Dose forte: quem falhar duas vezes seguidas também cai Inconsciente.","qtd":"1","excl":["Suporte","Cobra"]},{"name":"Granada Chamariz","tipo":"Lançável","pe":"0.5","acao":"Ação Bônus","mel":1,"desc":"Você arremessa a granada a até 15m. Por 1 minuto, ela reproduz disparos, passos e gritos de uma equipe inteira e aparece em sensores como alvos se movendo. Os inimigos que ouvirem fazem um teste de resistência de Sabedoria (CD 12 + Proef + Des). Na falha, tratam o ponto como uma ameaça real até verem que não há ninguém ali.","melhorias":"Sinal falso: a granada também aparece em câmeras térmicas como 3 pessoas.","qtd":"2","excl":["Cobra","Comando"]},{"name":"Machadinhas de Arremesso","tipo":"Lançável","pe":"0.5","acao":"Ação","mel":2,"desc":"Um par de machadinhas balanceadas para o arremesso, que não ocupam o espaço de arma. Faça um ataque à distância contra um alvo a até 6m (Proef + For). Num acerto, ele sofre 1d10 + For de dano cortante. Depois do combate, role 1d6 por machadinha usada: num 3 ou mais, ela é recuperada.","melhorias":"Cabo de fibra: o alcance sobe para 9m.\nGolpe de abertura: contra um alvo que ainda não agiu no combate, o acerto causa +1d6 de dano.","qtd":"2","excl":["Corpo-a-Corpo","Cobra"]},{"name":"Granada de Apagão","tipo":"Lançável","pe":"1","acao":"Ação","mel":1,"desc":"Você arremessa a granada a até 12m. Ela solta uma fumaça negra e um pulso que queima lâmpadas e telas num raio de 5m. A área fica em escuridão densa por 1 minuto, e nem NVG nem visão térmica enxergam dentro dela. Luzes elétricas a até 15m se apagam.","melhorias":"Pulso largo: a escuridão cobre um raio de 8m.","qtd":"1","excl":["Cobra","Hacker"]},{"name":"Bomba de Fuga","tipo":"Lançável","pe":"1","acao":"Ação Bônus","mel":1,"desc":"Quando a luta está perdida, a melhor jogada é sair dela.\nVocê estoura a bomba aos seus pés. Ela solta uma fumaça densa com raio de 6m que dura 1 minuto. No momento da explosão, você e cada aliado dentro da área podem usar a Reação para se mover até o Deslocamento deles sem provocar ataques de oportunidade.","melhorias":"Fumaça de sinal: o grupo recebe +2 nos testes de Furtividade para se esconder na próxima hora depois da fuga.","qtd":"1","excl":["Cobra","Comando"]},{"name":"Armadilha de Surpresa","tipo":"Armadilha","pe":"0.25","acao":"Ação","mel":1,"desc":"Você prende uma das suas granadas a uma porta, gaveta, mochila ou corpo caído. Quando alguém abrir ou mexer no objeto, a granada explode sem aviso, e os alvos têm Desvantagem no teste de resistência contra ela. A granada usada sai da quantidade dela.","melhorias":"Montagem limpa: notar a armadilha exige um teste de Investigação com Desvantagem.","qtd":"3","excl":["Cobra"]},{"name":"Projetor de Mira Múltipla \"Espectro\"","tipo":"Bateria","pe":"1","acao":"Ação Bônus","mel":2,"desc":"Gaste uma carga para arremessar o projetor a até 10m. Por 3 turnos, ele enche uma área com raio de 10m de pontos de mira falsos. Cada inimigo na área faz um teste de resistência de Sabedoria (CD 10 + Proef + Int) no início do turno. Na falha, tem Desvantagem nos ataques e não pode fazer ataques de oportunidade até o fim do turno. O projetor tem CA 10 e 5 PV.","melhorias":"Fogo de supressão falso: quem falhar também conta como Suprimido por 1 atacante.\nHolograma de calor: o efeito também engana visão térmica.","cargas":"2","excl":["Comando","Cobra"]},{"name":"Holograma","tipo":"Bateria","pe":"1","acao":"Ação","mel":2,"desc":"Gaste uma carga para lançar um projetor a até 12m. Ele cria a imagem de uma pessoa, de um objeto ou de você mesmo, que dura 1 minuto. Quem tocar na imagem ou passar num teste de Investigação (CD 10 + Proef + Int) percebe que é falsa.","melhorias":"Realismo: a imagem fala e se move, e a CD sobe +2.\nMovimentação: com uma Ação Bônus, você move a imagem até 6m.","cargas":"3","excl":["Cobra","Hacker"]},{"name":"\"ONYX\" Módulo de Dissipação","tipo":"Bateria","pe":"2","acao":"Ação Bônus","mel":2,"desc":"Gaste uma carga para ligar o campo por 5 turnos. Enquanto ele estiver ligado, você não aparece em câmeras, drones, sensores de movimento nem visão térmica. Pessoas ainda veem você a olho nu, mas você tem +2 em Furtividade contra quem depende de tecnologia.","melhorias":"Campo expandido: o efeito cobre também os aliados a até 2m de você.\nDesvio de assinatura: depois que o campo desliga, sensores e drones ainda veem você num ponto errado a até 9m por 2 turnos.","cargas":"2","excl":["Cobra"]},{"name":"Emissor Disruptor \"Silencer\"","tipo":"Bateria","pe":"1.5","acao":"Ação","mel":1,"desc":"Gaste uma carga para criar um campo com raio de 9m em volta de você por 1 minuto. Dentro dele, armas não fazem barulho para quem está fora, e alarmes sonoros não tocam. Você e os aliados na área têm Vantagem em Furtividade contra quem depende de audição.","melhorias":"Abafamento total: o campo também bloqueia comunicações de rádio que entram e saem dele.","cargas":"2","excl":["Cobra"]},{"name":"\"VOX\" Modulador Vocal","tipo":"Bateria","pe":"0.5","acao":"Ação Bônus","mel":2,"desc":"Um módulo preso à garganta que grava até 5 vozes e reproduz qualquer uma delas. Você tem Vantagem em Enganação para se passar por alguém só pela voz, como no rádio, no telefone ou atrás de uma porta. Ele não muda a sua aparência.","melhorias":"Síntese inteligente: você imita qualquer voz que tenha ouvido por 30 segundos, sem precisar gravar.\nFiltro emocional: a imitação também reproduz medo, dor e cansaço, e quem desconfiar tem Desvantagem para perceber.","excl":["Cobra"]},{"name":"\"LOCKBUG\" Abridor Universal","tipo":"Bateria","pe":"0.5","acao":"Ação","mel":2,"desc":"Um aparelho que abre fechaduras mecânicas simples e portas eletrônicas civis (Firewall 10) sem danificá-las. Você recebe +2 nos testes para abrir fechaduras, e cada tentativa leva uma Ação.","melhorias":"Auto-decodificador: a tentativa passa a usar uma Ação Bônus.\nBypass digital: também funciona em portas eletrônicas corporativas (Firewall 13).","excl":["Cobra","Hacker"]},{"name":"Pistola de Dardo \"STASIS\"","tipo":"Bateria","pe":"2","acao":"Ação","mel":1,"desc":"Faça um ataque à distância contra um alvo a até 12m (Proef + Des). Num acerto, ele faz um teste de resistência de Constituição (CD 10 + Proef + Int). Na falha, fica Paralisado. No fim de cada turno dele, ele repete o teste e o efeito acaba num sucesso, ou depois de 1 minuto.","melhorias":"Toxina de longa duração: o alvo tem Desvantagem no primeiro teste para encerrar o efeito.","cargas":"2","excl":["Suporte","Cobra"]},{"name":"Projetor de Distorção \"BLUR\"","tipo":"Bateria","pe":"2","acao":"Ação Bônus","mel":1,"desc":"Gaste a carga para ligar o projetor por 1 minuto. A sua imagem fica tremida e desfocada, e os ataques contra você têm Desvantagem. Quem enxerga sem depender da visão, como por radar ou sonar, não é afetado.","melhorias":"Bateria dupla: o projetor tem 2 cargas.","cargas":"1","excl":["Cobra","Corpo-a-Corpo"]},{"name":"Lançador de Boleadeiras","tipo":"Bateria","pe":"1","acao":"Ação","mel":2,"desc":"Uma pistola que dispara cordas com pesos nas pontas. Gaste uma carga e faça um ataque à distância contra um alvo a até 15m (Proef + Des). Num acerto, a corda se enrola nas pernas dele: ele fica Caído e Impedido até usar uma Ação e passar num teste de Força ou Acrobacia (CD 10 + Proef + Des). Não causa dano.","melhorias":"Corda de aço: a corda só pode ser cortada com uma arma cortante ou ferramenta, e a CD sobe +2.\nDisparo duplo: num acerto, você pode prender um segundo alvo a até 1,5m do primeiro.","cargas":"3","excl":["Suporte","Cobra"]},{"name":"Campo Refletor \"ESPELHO\"","tipo":"Bateria","pe":"2","acao":"Reação","mel":1,"desc":"Quando um equipamento mirar só você, como um dardo, um drone de choque, uma invasão de Sistema ou um efeito que exija teste de resistência só seu, use a Reação e gaste a carga. O efeito volta contra quem o usou, que faz o teste no seu lugar ou sofre o ataque, com os mesmos valores.","melhorias":"Espelho estável: o campo tem 2 cargas.","cargas":"1","excl":["Hacker","Cobra"]},{"name":"Propulsor de Salto \"BLINK\"","tipo":"Vestido / Bateria","pe":"1.5","acao":"Ação Bônus","mel":2,"desc":"Um propulsor compacto preso às costas. Gaste uma carga para se lançar até 9m para um ponto que você possa ver, inclusive para cima, sem provocar ataques de oportunidade. Você pousa de pé.","melhorias":"Duplo impulso: você pode se lançar duas vezes no mesmo turno, gastando uma carga em cada.\nCargas extras: o propulsor tem 3 cargas.","cargas":"2","excl":["Corpo-a-Corpo","Cobra"]},{"name":"Implante de Reflexo \"SANDEV\"","tipo":"Vestido","pe":"2.5","acao":"Ação Livre","mel":1,"desc":"Por um segundo, o mundo para. Você não.\nUm implante na coluna que acelera o seu sistema nervoso. Uma vez por descanso longo, no começo do seu turno, você pode ativar o implante: neste turno, você ganha uma Ação extra completa. No fim do turno, você sofre 1 nível de exaustão. O implante é um Sistema e pode ser invadido.","melhorias":"Resfriamento: em vez de exaustão, você perde 2d6 Pontos de Vontade.","excl":["Corpo-a-Corpo","Cobra"]},{"name":"Leitor de Microexpressões","tipo":"Vestido / Bateria","pe":"1.5","acao":"Ação Bônus","mel":1,"desc":"Óculos com câmera e análise de rosto. Com uma Ação Bônus, você analisa um alvo a até 9m que possa ver. Até o fim da conversa, você sabe quando ele está nervoso, com medo ou mentindo, e tem Vantagem nos testes de Intuição contra ele. Quem estiver de máscara ou com o rosto coberto não pode ser lido.","melhorias":"Banco de rostos: o leitor também diz se o alvo aparece em algum registro que você tenha baixado.","excl":["Cobra","Comando"]},{"name":"Capa de Emboscada","tipo":"Vestido","pe":"1.5","acao":"Ação Livre","mel":1,"desc":"Quem ataca da sombra não fica parado esperando a explosão.\nUma capa leve de tecido refletor. Quando você fizer um teste de resistência de Destreza contra um efeito em área, como uma granada, sofre metade do dano numa falha e nenhum dano num sucesso. Enquanto você estiver em penumbra ou escuridão e não tiver atacado no turno, os ataques à distância contra você têm Desvantagem.","melhorias":"Forro térmico: a capa também esconde você de visão térmica enquanto estiver parado.","excl":["Cobra","Corpo-a-Corpo"]},{"name":"Luvas de Escalada Magnéticas","tipo":"Vestido / Bateria","pe":"1","acao":"Ação Bônus","mel":2,"desc":"Gaste uma carga para ligar as luvas e as solas por 10 minutos. Você escala paredes, tetos e superfícies verticais com o seu Deslocamento normal, sem teste e com as mãos livres para segurar uma arma de uma mão. Em superfícies de metal, você também pode ficar pendurado de cabeça para baixo.","melhorias":"Aderência total: as luvas funcionam também em vidro e superfícies molhadas.\nBateria longa: as luvas duram 1 hora por carga.","cargas":"2","excl":["Corpo-a-Corpo","Cobra"]},{"name":"\"FULTON\" Kit de Extração","tipo":"Consumível","pe":"0.5","acao":"Ação","mel":2,"desc":"Você prende o balão num alvo a até 1,5m, de até 150kg, num local aberto. Se ele estiver Inconsciente, Atordoado, Paralisado ou preso, o engate é automático. Se puder resistir, ele faz um teste de resistência de Força (CD 10 + Proef + Des) para se soltar. No início do seu próximo turno, o balão sobe e o alvo é extraído para fora da cena, vivo. Antes disso, o balão pode ser destruído (CA 8, 15 PV), e o alvo cai Caído.","melhorias":"Balão reforçado: o balão tem CA 12 e 30 PV.\nCarga pesada: o balão leva até 300kg, como uma caixa de suprimentos ou uma moto.","qtd":"1","excl":["Cobra","Comando"]},{"name":"Termite","tipo":"Consumível","pe":"0.75","acao":"Ação","mel":1,"desc":"Uma carga de termite que queima a 2.000 graus. Em 1 turno, ela derrete uma fechadura, uma dobradiça, um cadeado ou uma chapa de metal de até 5cm, sem explosão e quase sem barulho. Um veículo atingido no motor para de funcionar.","melhorias":"Carga em fita: a termite corta um buraco do tamanho de uma porta numa chapa de metal.","qtd":"2","excl":["Cobra"]},{"name":"Veneno de Lâmina","tipo":"Consumível","pe":"0.5","acao":"Ação Bônus","mel":1,"desc":"Você passa o veneno numa arma branca ou em 3 facas de arremesso. O próximo acerto com ela, até o fim da cena, faz o alvo testar Constituição (CD 10 + Proef + Int). Na falha, ele sofre 2d6 de dano extra e fica Envenenado por 1 minuto.","melhorias":"Toxina paralisante: um alvo que falhar por 5 ou mais também fica Impedido até o fim do próximo turno dele.","qtd":"3","excl":["Cobra"]},{"name":"Seringa Sedativa","tipo":"Consumível","pe":"0.75","acao":"Ação","mel":1,"desc":"Faça um ataque corpo a corpo contra um alvo a até 1,5m. Num acerto, ele faz um teste de resistência de Constituição (CD 10 + Proef + Int). Na falha, fica Envenenado e cai Inconsciente no fim do próximo turno dele, por 10 minutos. Se estiver fora de combate, cai Inconsciente na hora.","melhorias":"Dose rápida: num alvo Surpreendido ou Agarrado, ele cai Inconsciente na hora, mesmo em combate.","qtd":"2","excl":["Cobra","Suporte"]},{"name":"Ácido Concentrado","tipo":"Consumível","pe":"0.5","acao":"Ação","mel":1,"desc":"Um frasco de ácido de alta corrosão. Em 1 minuto, ele dissolve uma fechadura, uma corrente ou uma grade. Arremessado num alvo a até 6m (ataque à distância, Proef + Des), causa 2d6 de dano incendiário e o colete dele perde 1 de CA até ser reparado.","melhorias":"Gel ácido: o ácido age em 1 turno em vez de 1 minuto.","qtd":"2","excl":["Cobra"]},{"name":"Bolsa de Sangue Falso","tipo":"Consumível","pe":"0.25","acao":"Ação","mel":1,"desc":"Às vezes a melhor jogada é morrer de mentira.\nVocê estoura a bolsa e se joga no chão. Quem não tiver certeza de que você está vivo faz um teste de Medicina ou Investigação contra a sua Atuação, com Desvantagem. Na falha, acredita que você morreu.","melhorias":"Inibidor de pulso: o seu pulso fica fraco por 1 minuto, e nem um exame de perto mostra que você está vivo sem um teste de Medicina com Desvantagem.","qtd":"2","excl":["Cobra"]},{"name":"Soro da Verdade","tipo":"Consumível","pe":"1","acao":"Ação","mel":1,"desc":"Você aplica o soro num alvo preso ou inconsciente. Por 10 minutos, ele faz um teste de resistência de Sabedoria (CD 10 + Proef + Int) a cada pergunta direta. Na falha, ele responde com a verdade, mas pode responder o mínimo possível.","melhorias":"Fórmula limpa: o alvo não se lembra do interrogatório depois que o efeito acaba.","qtd":"1","excl":["Cobra","Comando"]},{"name":"Granada P.E.M.","tipo":"Lançável","pe":"1","acao":"Ação","mel":2,"desc":"Você arremessa a granada a até 12m. Ela solta um pulso eletromagnético num raio de 5m. Drones, câmeras, torretas e equipamentos com Bateria na área ficam desativados até o fim do seu próximo turno. Um equipamento pessoal resiste se o dono passar num teste de resistência de Inteligência (CD 10 + Proef + Des). Um alvo com Sistema interno faz um teste de resistência de Constituição com a mesma CD: na falha, perde a Reação e tem Desvantagem no próximo ataque.","melhorias":"Pulso ampliado: o raio sobe para 8m.\nPulso longo: os Sistemas ficam desativados por 1 minuto.","qtd":"2","excl":["Hacker"]},{"name":"Chaff Anti-drone","tipo":"Lançável","pe":"0.75","acao":"Ação Bônus","mel":1,"desc":"Você arremessa a granada a até 15m. Ela solta uma nuvem de fitas metálicas com raio de 6m que dura 1 minuto. Drones dentro da nuvem perdem o controle remoto e só agem por conta própria, e disparos guiados ou sensores de radar não localizam alvos dentro dela.","melhorias":"Carga magnética: drones dentro da nuvem também caem e ficam desativados até o fim do seu próximo turno.","qtd":"2","excl":["Hacker","Comando"]},{"name":"Placa de Choque","tipo":"Armadilha","pe":"1","acao":"Ação","mel":1,"desc":"Uma placa fina de 1,5m que se esconde sob tapetes e entulho. Quando um alvo pisar nela, ele faz um teste de resistência de Constituição (CD 10 + Proef + Des). Na falha, sofre 2d8 de dano elétrico e fica Atordoado até o fim do próximo turno dele. No sucesso, sofre metade. Mecanizados e alvos com Sistema interno têm Desvantagem no teste. A placa dispara uma vez por carga.","melhorias":"Placa larga: a placa cobre 3m por 3m.","qtd":"3","excl":["Hacker"]},{"name":"Mina de Pulso P.E.M.","tipo":"Armadilha","pe":"1","acao":"Ação","mel":1,"desc":"A mina detecta motores e circuitos. Quando um veículo, drone, torreta ou alvo com Sistema interno chegar a 3m dela, ela solta um pulso com raio de 5m que funciona como a Granada P.E.M.","melhorias":"Pulso pesado: veículos atingidos também param por 1 turno.","qtd":"1","excl":["Hacker"]},{"name":"PDI","tipo":"Bateria (Ferramenta de hacking)","pe":"1","acao":"Ação","mel":2,"desc":"Um computador de pulso. Funciona como ferramenta de hacking com alcance de 18m e +0 no teste de invasão. Fica preso ao pulso, então você invade sem soltar a arma. É a ferramenta inicial do Hacker.","melhorias":"PDI blindado: o seu Firewall pessoal recebe +2.\nTela holográfica: um aliado a até 1,5m pode ver o que você vê no Sistema invadido.","excl":["Hacker"]},{"name":"Notebook de Campo","tipo":"Bateria (Ferramenta de hacking)","pe":"1.5","acao":"Ação","mel":2,"desc":"Funciona como ferramenta de hacking com alcance de 18m e +3 no teste de invasão. Ocupa as duas mãos enquanto você invade, e no turno em que invadir você não pode atacar com arma de duas mãos.","melhorias":"Antena de longo alcance: se você não se mover no turno, o alcance sobe para 36m.\nProcessador extra: uma vez por descanso curto, você rola o teste de invasão duas vezes e usa o maior resultado.","excl":["Hacker"]},{"name":"\"SPYDER\" Módulo de Intrusão","tipo":"Bateria (Ferramenta de hacking)","pe":"1","acao":"Ação","mel":2,"desc":"Um módulo do tamanho de uma aranha que anda até 6m e se conecta sozinho a um Sistema. Gaste uma carga para enviar o SPYDER: enquanto ele estiver conectado, você invade aquele Sistema como se estivesse conectado fisicamente, de qualquer distância, e recebe +2 no teste.","melhorias":"Camuflagem: notar o SPYDER exige um teste de Investigação (CD 10 + Proef + Int).\nVírus de trava: um Sistema afetado por Interferir através do SPYDER fica travado até o fim do seu turno seguinte também.","cargas":"3","excl":["Hacker"]},{"name":"Lançador de Vírus \"Tifão\"","tipo":"Bateria","pe":"2","acao":"Ação","mel":1,"desc":"Uma pistola de dardos com chips de vírus. Faça um ataque à distância contra um alvo a até 18m (Proef + Des). Num acerto, o dardo se conecta a um Sistema do alvo, e você faz um teste de invasão contra ele na mesma Ação, sem precisar de linha de visão depois disso.","melhorias":"Vírus em cadeia: se a invasão funcionar, você pode repetir o mesmo nível contra outro Sistema a até 6m do alvo, sem gastar outra carga.","cargas":"2","excl":["Hacker"]},{"name":"\"VÍBORA\" Drone de Choque","tipo":"Bateria","pe":"2.5","acao":"Ação","mel":2,"desc":"Um drone de ataque que voa até 18m de você. Com uma Ação Bônus, você move o drone até 12m e gasta uma carga para ele disparar num alvo a até 3m dele: o alvo faz um teste de resistência de Constituição (CD 10 + Proef + Int). Na falha, sofre 2d8 de dano elétrico e perde a Reação até o início do próximo turno dele. No sucesso, sofre metade. O drone tem CA 14 e 15 PV.","melhorias":"Dardo paralisante: um alvo que falhar por 5 ou mais fica Atordoado até o fim do próximo turno dele.\nBateria de choque: o drone tem 5 cargas.","cargas":"3","excl":["Hacker"]},{"name":"\"VULTURE\" Torreta Autônoma","tipo":"Bateria","pe":"2","acao":"Ação","mel":2,"desc":"Você monta a torreta num ponto a até 1,5m. No início de cada um dos seus turnos, ela gasta uma carga e ataca o inimigo mais próximo a até 15m, com Precisão igual à sua Proef + Int, causando 2d6 de dano perfurante. Você pode mandar ela só atacar quem atacar você ou os seus aliados. A torreta tem CA 15 e 20 PV.","melhorias":"Munição aprimorada: o dano sobe para 3d6.\nAutodestruição: quando a torreta for destruída ou ficar sem carga, ela explode num raio de 3m, causando 2d8 de dano explosivo (teste de Destreza, CD 10 + Proef + Int, para metade).","cargas":"6","excl":["Hacker"]},{"name":"\"WASP\" Drone Kamikaze","tipo":"Bateria","pe":"1.5","acao":"Ação","mel":2,"desc":"Um quadricóptero com uma carga explosiva. Gaste uma carga para lançar o drone: ele voa até 30m e explode num raio de 2m. Cada alvo na área faz um teste de resistência de Destreza (CD 10 + Proef + Int). Na falha, sofre 3d8 de dano explosivo. No sucesso, sofre metade. O drone contorna coberturas, então cobertura parcial não ajuda no teste.","melhorias":"Carga perfurante: o drone causa o dobro de dano em veículos e coberturas.\nVoo rasteiro: notar o drone chegando exige um teste de Percepção (CD 10 + Proef + Int), e quem falhar tem Desvantagem no teste de resistência.","cargas":"2","excl":["Hacker"]},{"name":"Drone Relé","tipo":"Bateria","pe":"1","acao":"Ação Bônus","mel":1,"desc":"Um drone que fica parado no ar a até 30m de você, por até 1 hora, repetindo sinais. Enquanto ele estiver ativo, os pontos e rádios do grupo funcionam a até 10km, e você pode usar a sua ferramenta de hacking como se estivesse na posição do drone.","melhorias":"Furtivo: notar o drone no céu exige um teste de Percepção (CD 10 + Proef + Int).","excl":["Comando","Hacker"]},{"name":"Firewall Reativo \"AEGIS-NET\"","tipo":"Bateria","pe":"1.5","acao":"Reação","mel":2,"desc":"Quando um Sistema seu ou de um aliado a até 9m for alvo de um teste de invasão, use a Reação e gaste uma carga. Faça um teste de Inteligência + Proef contra o resultado do invasor. Se você igualar ou superar, a invasão falha e o Código gasto, se houver, é perdido.","melhorias":"Contra-ataque: se a invasão falhar por causa do AEGIS-NET, você sabe a posição do invasor até o fim do seu próximo turno.\nEscudo amplo: o alcance sobe para 18m.","cargas":"2","excl":["Hacker"]},{"name":"\"CHIMERA\" Projetor de IFF Dinâmico","tipo":"Bateria","pe":"2","acao":"Ação Bônus","mel":2,"desc":"Um sistema experimental que falsifica a assinatura de amigo ou inimigo dos sistemas de combate.\nGaste uma carga para ligar o projetor por 5 turnos. Enquanto ele estiver ligado, torretas automáticas, drones armados, minas inteligentes e sistemas automáticos de defesa tratam você como uma unidade aliada: não atacam você e não detonam por sua causa. Inimigos que dependem só de sensores eletrônicos para mirar têm Desvantagem nos ataques contra você. Se você atacar ou invadir um desses sistemas, o efeito acaba para aquele sistema.","melhorias":"Assinatura de grupo: o efeito também cobre um aliado a até 3m de você.\nOrdem falsa: com uma Ação, você manda um desses sistemas, que trate você como aliado, atacar outro alvo uma vez.","cargas":"2","excl":["Hacker"]},{"name":"Unidade de Apoio \"ÓRBITA\"","tipo":"Bateria","pe":"2.5","acao":"Ação Bônus","mel":2,"desc":"Uma pequena unidade flutuante que acompanha o operador e nunca para de falar em tom formal.\nA unidade flutua ao seu lado e se move com você. Uma vez por turno, com uma Ação Bônus, ela dispara num alvo a até 18m, com Precisão igual à sua Proef + Int, causando 1d6 + Int de dano perfurante. Com uma Ação, você gasta uma carga para ela executar um programa: Laser (uma linha de 18m, teste de Destreza CD 10 + Proef + Int para metade de 3d8 de dano incendiário) ou Escudo (você ganha 1d8 + Int pontos de vida temporários). A unidade tem CA 15 e 15 PV.","melhorias":"Programa Martelo: um novo programa: a unidade cai sobre um alvo a até 3m dela, que faz um teste de Força (mesma CD) ou fica Caído e sofre 2d8 de dano contundente.\nMódulo de voo: enquanto você estiver caindo, a unidade segura você e você desce devagar, sem sofrer dano de queda.","cargas":"3","excl":["Hacker","Comando"]},{"name":"Rádio de Ressonância","tipo":"Bateria","pe":"1.5","acao":"Ação","mel":2,"desc":"Algumas frequências fazem as máquinas lembrarem de coisas que não deveriam.\nUm rádio de onda curta com um sintonizador estranho. Com uma Ação, você varre as frequências: descobre transmissões escondidas, sinais criptografados e aparelhos ligados a até 100m, e consegue ouvir mensagens cifradas comuns. Gaste uma carga para emitir uma frequência de ressonância num raio de 9m: cada alvo com Sistema interno ou que seja Replika faz um teste de resistência de Sabedoria (CD 10 + Proef + Int). Na falha, fica Atordoado até o fim do próximo turno dele. Aliados na área também precisam fazer o teste.","melhorias":"Frequência sintonizada: você escolhe até 3 alvos na área que não são afetados.\nSinal de memória: um alvo que falhar também revela uma lembrança ou informação que tenha gravado, à escolha do mestre.","cargas":"2","excl":["Hacker","Suporte"]},{"name":"Módulo de Estase","tipo":"Bateria","pe":"2","acao":"Ação","mel":1,"desc":"Às vezes você só precisa que o mundo vá mais devagar.\nUm módulo preso ao braço que dispara um campo de estase. Gaste uma carga e escolha um alvo a até 18m. Ele faz um teste de resistência de Constituição (CD 10 + Proef + Int). Na falha, fica lento por 1 minuto: o Deslocamento cai pela metade, ele não pode usar Reações e, em cada turno, só pode usar uma Ação ou uma Ação Bônus, não as duas. Ele repete o teste no fim de cada turno dele e o efeito acaba num sucesso. O módulo também desacelera objetos, como uma porta se fechando ou um ventilador, por 1 minuto.","melhorias":"Campo largo: o efeito atinge até 3 alvos a até 3m um do outro.","cargas":"2","excl":["Hacker","Corpo-a-Corpo"]},{"name":"Chips de Otimização","tipo":"Vestido","pe":"1","acao":"Ação Livre","mel":2,"desc":"Uma placa de encaixes para quem tem Sistema interno ou é um Construto, como Replikas, Mecanizados e autômatos. Durante um descanso longo, escolha 2 chips para ficarem instalados: Autorreparo (fora de combate, você recupera 1 PV por minuto); Contra-ataque (uma vez por turno, quando um ataque corpo a corpo errar você, você pode fazer um ataque corpo a corpo contra o atacante com a Reação); Evasão (+1 de CA contra ataques de oportunidade e +1,5m de Deslocamento); ou Mira Assistida (+1 de Precisão em disparos contra alvos a mais de 30m). Os chips são parte do Sistema e podem ser invadidos.","melhorias":"Placa expandida: você instala 3 chips em vez de 2.\nChip de Reboot: um novo chip: uma vez por descanso longo, ao cair a 0 PV, você volta com 1 PV no início do seu próximo turno.","excl":["Hacker","Corpo-a-Corpo"]},{"name":"Granada Criogênica","tipo":"Lançável","pe":"1.25","acao":"Ação","mel":1,"desc":"Você arremessa a granada a até 12m. Ela libera um gás criogênico num raio de 3m. Cada alvo na área faz um teste de resistência de Constituição (CD 10 + Proef + Des). Na falha, sofre 2d6 de dano perfurante pelos cristais de gelo e fica Congelado. No sucesso, sofre metade. O chão da área fica escorregadio e conta como terreno difícil por 1 minuto.","melhorias":"Gelo seco: a área também bloqueia visão térmica enquanto o chão estiver congelado.","qtd":"1","excl":["Suporte"]},{"name":"Granada Corrosiva","tipo":"Lançável","pe":"1","acao":"Ação","mel":1,"desc":"Você arremessa a granada a até 12m. Ela espalha ácido num raio de 2m. Coberturas e objetos na área perdem 20 PV. Cada alvo na área faz um teste de resistência de Destreza (CD 10 + Proef + Des). Na falha, o colete dele perde 1 de CA até ser reparado num descanso longo, até um máximo de 2 de perda.","melhorias":"Ácido concentrado: as coberturas e objetos perdem 30 PV, e o máximo de perda de CA do colete sobe para 3.","qtd":"1","excl":["Suporte"]},{"name":"Granada Anti-cura","tipo":"Lançável","pe":"1","acao":"Ação","mel":1,"desc":"Você arremessa a granada a até 12m. Ela estoura num raio de 3m com um composto que age diferente em cada corpo. Os inimigos na área fazem um teste de resistência de Constituição (CD 10 + Proef + Int). Na falha, não podem recuperar pontos de vida até o fim do seu próximo turno. Os aliados na área recuperam 2d6 pontos de vida.","melhorias":"Composto forte: os inimigos que falharem ficam sem cura até o fim do seu segundo turno seguinte.","qtd":"2","excl":["Suporte","Comando"]},{"name":"Mina de Gás","tipo":"Armadilha","pe":"0.75","acao":"Ação","mel":1,"desc":"Ao posicionar, escolha o gás: lacrimogêneo ou sedativo. Quando um alvo chegar a 2m da mina, ela solta uma nuvem com raio de 4m que funciona como a granada do mesmo gás.","melhorias":"Dois cilindros: a mina solta os dois gases ao mesmo tempo.","qtd":"1","excl":["Suporte"]},{"name":"\"D.A.R.T.\" Drone de Resgate","tipo":"Bateria","pe":"1.5","acao":"Ação","mel":2,"desc":"Um drone médico que voa até um aliado ferido a até 10m. Gaste uma carga: o aliado recupera 2d6 + Int ou Sab pontos de vida, o que for maior. Se ele estiver com 0 PV, também fica estabilizado.","melhorias":"Nanoinjeção: a cura sobe para 3d6 + Int ou Sab.\nModo de assistência: você pode deixar o drone seguindo um aliado. Quando ele cair abaixo de metade dos PV, o drone gasta uma carga e cura sozinho, sem usar a sua Ação.","cargas":"3","excl":["Suporte"]},{"name":"\"MULA\" Drone de Carga","tipo":"Bateria","pe":"1","acao":"Ação Bônus","mel":2,"desc":"Um drone terrestre de quatro rodas que segue você a até 10m e carrega até 6 de Carga para o grupo. Com uma Ação Bônus, você manda o drone até 20m para entregar um item a um aliado, que pode pegar o item sem gastar Ação. O drone tem CA 12 e 20 PV.","melhorias":"Blindagem: o drone conta como cobertura Média para quem estiver atrás dele.\nEsteiras: o drone sobe escadas e atravessa terreno difícil sem perder velocidade.","excl":["Suporte"]},{"name":"Desfibrilador \"RESTART\"","tipo":"Bateria","pe":"2.5","acao":"Ação","mel":2,"desc":"Você usa o desfibrilador num aliado a até 1,5m que tenha morrido ou caído com 0 PV nos últimos 2 turnos e cujo corpo não tenha sido destruído. Faça um teste de Medicina (CD 12). No sucesso, ele volta com 1d4 PV. Na falha, ele fica estabilizado, mas continua inconsciente.","melhorias":"Nanocura: o aliado volta com 1d8 + Int ou Sab PV.\nCapacitor de emergência: se o teste falhar, o desfibrilador recarrega sozinho depois de 2 turnos para uma nova tentativa.","cargas":"1","excl":["Suporte"]},{"name":"Pistola de Estímulo MPD-0","tipo":"Bateria","pe":"1.5","acao":"Ação","mel":2,"desc":"Uma pistola de ar comprimido com seringas. Gaste uma carga para atingir você ou um aliado a até 10m, sem teste: o alvo recupera 2d8 + Int ou Sab pontos de vida, o que for maior. Um alvo com 0 PV também fica estabilizado e pode se levantar.","melhorias":"Estimulante de combate: o alvo curado tem Vantagem no próximo ataque que fizer no turno dele.\nAuto-injetor: usar a pistola em você mesmo passa a usar uma Ação Bônus.","cargas":"3","excl":["Suporte"]},{"name":"Módulo de Autorreparo","tipo":"Bateria","pe":"1","acao":"Ação Bônus","mel":1,"desc":"Um módulo de nanomáquinas para Construtos, como Replikas, Mecanizados e autômatos. Gaste uma carga: você, ou um Construto a até 1,5m, recupera 1d8 + Int pontos de vida.","melhorias":"Reparo contínuo: o alvo também recupera 2 PV no início de cada turno dele por 3 turnos.","cargas":"3","excl":["Suporte"]},{"name":"Escâner Médico","tipo":"Bateria","pe":"0.75","acao":"Ação","mel":1,"desc":"Você escaneia um alvo a até 1,5m. Descobre quantos pontos de vida ele tem, os estados que o afetam, venenos, doenças e implantes. Você tem Vantagem no próximo teste de Medicina para tratar esse alvo.","melhorias":"Leitura à distância: o escaneamento pode ser feito a até 9m, sem tocar no alvo.","excl":["Suporte"]},{"name":"Estação Médica Portátil","tipo":"Bateria","pe":"2","acao":"Ação","mel":1,"desc":"Gaste a carga para montar a estação num ponto a até 1,5m. Por 3 turnos, no início do turno de cada aliado a até 3m dela, ele recupera 1d6 pontos de vida. A estação tem CA 12 e 15 PV.","melhorias":"Nebulizador: a cura sobe para 1d8, e o raio sobe para 5m.","cargas":"1","excl":["Suporte"]},{"name":"Domo de Contenção","tipo":"Bateria","pe":"2","acao":"Ação Bônus","mel":2,"desc":"Você planta o gerador no chão. Ele cria uma cúpula de energia com raio de 3m em volta dele, que dura até o fim do seu próximo turno. Disparos, granadas e projéteis não atravessam a cúpula em nenhum sentido, então quem está dentro tem cobertura total contra quem está fora. Pessoas podem entrar e sair dela andando.","melhorias":"Gerador duplo: o gerador tem 2 cargas.\nCúpula estável: a cúpula dura até o fim do seu segundo turno seguinte.","cargas":"1","excl":["Comando","Suporte"]},{"name":"Drone de Nanoesporos Criogênicos","tipo":"Bateria","pe":"2.5","acao":"Ação","mel":2,"desc":"Esporos sintéticos que congelam a ferida e fecham o corte antes do sangue sair.\nGaste uma carga para o drone lançar um dispositivo num ponto a até 12m. Ele libera uma névoa fria de nanoesporos com raio de 3m que dura 3 turnos. Cada aliado que começar o turno dentro da névoa recupera 1d10 pontos de vida, até um máximo de 3d10 por dispositivo para cada aliado. Um aliado com 0 PV que estiver na névoa fica estabilizado.","melhorias":"Esporos densos: a cura sobe para 1d12 por turno, até um máximo de 3d12.\nNévoa ampla: o raio sobe para 5m.","cargas":"2","excl":["Comando","Suporte"]},{"name":"Gerador de Barreira \"PROTEGER\"","tipo":"Bateria","pe":"1.5","acao":"Ação Bônus","mel":2,"desc":"Gaste uma carga para cobrir você ou um aliado a até 9m com uma barreira por 1 minuto. Escolha o modo ao ativar. Modo Proteção: o dano de armas que o alvo sofrer é reduzido em 3. Modo Escudo: o dano elétrico, incendiário e de equipamentos que o alvo sofrer é reduzido pela metade.","melhorias":"Barreira dupla: a mesma carga ativa os dois modos ao mesmo tempo.\nProjeção em grupo: a carga cobre até 3 aliados a até 9m.","cargas":"3","excl":["Suporte","Comando"]},{"name":"Injetor em Cadeia","tipo":"Bateria","pe":"2","acao":"Ação","mel":2,"desc":"Uma pistola médica que dispara uma seringa com microdrones. Gaste uma carga e escolha um aliado a até 12m: ele recupera 2d6 + Int ou Sab pontos de vida. Depois, os drones saltam para até 2 outros aliados a até 6m do primeiro, que recuperam metade disso.","melhorias":"Cadeia longa: os drones saltam para até 3 aliados.\nCoagulante: cada aliado curado também para de piorar de um ferimento crítico até ser tratado.","cargas":"3","excl":["Suporte"]},{"name":"Robô Médico Compacto","tipo":"Bateria","pe":"2","acao":"Ação","mel":2,"desc":"Um robô de rodas do tamanho de um cachorro, com um braço médico. Você posiciona o robô num ponto a até 1,5m, e ele fica ativo por 1 hora. No início de cada um dos seus turnos, ele cura 1d6 pontos de vida do aliado mais ferido a até 6m dele e se move até 6m para ficar perto dos aliados. O robô tem CA 13 e 15 PV e não ataca.","melhorias":"Kit avançado: a cura sobe para 1d8 + Int.\nRodas de esteira: o robô atravessa escadas e terreno difícil sem perder velocidade.","excl":["Suporte"]},{"name":"Traje Hazmat","tipo":"Vestido","pe":"1","acao":"Ação","mel":2,"desc":"Um traje selado contra agentes químicos, biológicos e radiação. Enquanto estiver vestido, você é imune a gases e tem Vantagem nos testes contra venenos, doenças e contaminação, inclusive por exposição ao Originium. Ele dura 4 horas por cilindro de ar, e vestir o traje leva 1 minuto.","melhorias":"Traje reforçado: o traje também dá resistência a dano incendiário e elétrico.\nEngate rápido: vestir o traje leva uma Ação.","excl":["Suporte"]},{"name":"Kit Médico Avançado","tipo":"Consumível","pe":"1.5","acao":"Ação","mel":2,"desc":"Você trata um aliado a até 1,5m. Ele recupera 2d6 + Int ou Sab pontos de vida, o que for maior. Um aliado com 0 PV também fica estabilizado, sem teste de Medicina.","melhorias":"Nanomeds: a cura sobe para 3d6 + Int ou Sab.\nAutoaplicação: usar o kit em você mesmo passa a usar uma Ação Bônus.","qtd":"3","excl":["Suporte"]},{"name":"Injetor de Adrenalina","tipo":"Consumível","pe":"1","acao":"Ação Bônus","mel":1,"desc":"Você aplica o injetor em você ou num aliado a até 1,5m. Até o fim do próximo turno do alvo, ele ganha +3m de Deslocamento e Vantagem nos testes de resistência de Força e Constituição. Quando o efeito acaba, ele perde 1d6 Pontos de Vontade.","melhorias":"Dose limpa: o alvo não perde Pontos de Vontade quando o efeito acaba.","qtd":"2","excl":["Suporte","Corpo-a-Corpo"]},{"name":"Injetor de Morfina","tipo":"Consumível","pe":"0.75","acao":"Ação Bônus","mel":1,"desc":"Você aplica a morfina em você ou num aliado a até 1,5m. Ele ganha 2d6 pontos de vida temporários e ignora a penalidade de um ferimento crítico até o fim da cena. Ele tem Desvantagem em Percepção enquanto o efeito durar.","melhorias":"Dose militar: os pontos de vida temporários sobem para 3d6.","qtd":"2","excl":["Suporte"]},{"name":"Antídoto Universal","tipo":"Consumível","pe":"0.5","acao":"Ação","mel":1,"desc":"Você aplica o antídoto em você ou num aliado a até 1,5m. O estado Envenenado acaba, e o alvo tem Vantagem nos testes contra venenos por 1 hora.","melhorias":"Soro largo: o antídoto também cura doenças comuns e o efeito de gases sedativos.","qtd":"2","excl":["Suporte"]},{"name":"Supressor de Oripatia","tipo":"Consumível","pe":"1","acao":"Ação","mel":1,"desc":"Não cura. Ganha tempo.\nUm remédio caro que alivia os sintomas da Oripatia. Por 24 horas, o alvo não sente as dores da doença, e os cristais não avançam nesse período. Não remove a Oripatia nem os cristais que já existem.","melhorias":"Dose concentrada: o efeito dura 72 horas.","qtd":"1","excl":["Suporte"]},{"name":"\"PHOENIX\" Injetor de Adrenalina Militar","tipo":"Consumível","pe":"2.5","acao":"Ação","mel":2,"desc":"Uma seringa experimental de estimulantes pesados. Ninguém sai inteiro do outro lado.\nVocê aplica o injetor em você ou num aliado a até 1,5m. Durante 3 turnos, o alvo recebe +5m de Deslocamento e +2 de CA, levantar do chão não gasta movimento, e ele ganha uma Ação extra por turno. Essa Ação extra só pode ser usada para fazer um ataque (um disparo, que sofre Recuo normalmente), Disparada, Desengajar, Esconder ou usar um objeto. Quando o efeito acaba, o alvo não pode se mover nem usar Ações durante o próximo turno dele. Um alvo só pode receber uma dose por descanso longo.","melhorias":"Dose estabilizada: quando o efeito acaba, o alvo pode se mover e usar a Ação normalmente, mas perde 1d6 Pontos de Vontade.\nDose dupla: a quantidade sobe para 2, mas cada alvo continua limitado a uma dose por descanso longo.","qtd":"1","excl":["Suporte"]},{"name":"Nanites de Regeneração \"REGEN\"","tipo":"Consumível","pe":"1","acao":"Ação Bônus","mel":1,"desc":"Você aplica as nanites em você ou num aliado a até 1,5m. Por 1 minuto, no início de cada turno do alvo, ele recupera 1d4 + Con pontos de vida. O efeito para se o alvo cair a 0 PV.","melhorias":"Enxame denso: a cura sobe para 1d6 + Con por turno.","qtd":"2","excl":["Suporte"]},{"name":"Remédio Universal","tipo":"Consumível","pe":"0.75","acao":"Ação","mel":1,"desc":"Um coquetel que trata quase tudo de uma vez. Você aplica em você ou num aliado a até 1,5m, e acabam os estados Envenenado, Cego, Surdo, Queimado e Congelado. O alvo também perde 1 nível de Estafa.","melhorias":"Fórmula completa: o remédio também acaba com o estado Amedrontado e com os efeitos de gás.","qtd":"2","excl":["Suporte"]},{"name":"Plataforma de Salto","tipo":"Lançável","pe":"1","acao":"Ação Bônus","mel":1,"desc":"Você arremessa a plataforma a até 6m. Ela fica ativa por 1 minuto. Quem pisar nela, aliado ou inimigo, pode ser lançado até 10m em qualquer direção, inclusive para cima, e pousa sem dano. Lançar um inimigo exige que ele falhe num teste de Destreza (CD 10 + Proef + Des) ao pisar nela.","melhorias":"Mola dupla: o lançamento chega a 15m.","qtd":"1","excl":["Corpo-a-Corpo","Comando"]},{"name":"Kunai de Corrente","tipo":"Lançável","pe":"0.75","acao":"Ação","mel":2,"desc":"Vem cá.\nUma lâmina presa a uma corrente de 9m. Faça um ataque à distância contra um alvo a até 9m (Proef + Des). Num acerto, ele sofre 1d6 + Des de dano perfurante e faz um teste de resistência de Força (CD 10 + Proef + Des). Na falha, é puxado até um espaço ao seu lado. A kunai volta para a sua mão logo depois e não se gasta.","melhorias":"Golpe de chegada: se o alvo for puxado, você pode fazer um ataque corpo a corpo contra ele com a Ação Bônus.\nCorrente longa: o alcance sobe para 15m.","qtd":"1","excl":["Corpo-a-Corpo"]},{"name":"Onda de Choque \"Behemoth\"","tipo":"Bateria","pe":"2","acao":"Ação","mel":2,"desc":"Dispositivo nas botas. Gaste uma carga e pise com força: cada alvo a até 5m faz um teste de resistência de Força (CD 10 + Proef + Con). Na falha, sofre 3d8 de dano contundente e é empurrado 3m. No sucesso, sofre metade e não é empurrado.","melhorias":"Abalo: quem falhar também fica Caído.\nFoco: em vez do raio, a onda pode sair num cone de 9m.","cargas":"3","excl":["Corpo-a-Corpo"]},{"name":"Investida Cinética","tipo":"Bateria","pe":"1.5","acao":"Ação","mel":1,"desc":"Um módulo nos sapatos que solta um impulso. Gaste uma carga para avançar até 6m em linha reta, atravessando obstáculos leves. Se terminar ao lado de um inimigo, ele sofre 1d10 + For de dano contundente e faz um teste de resistência de Força (CD 10 + Proef + For). Na falha, fica Caído. Durante a investida, você tem +2 de CA contra ataques de oportunidade.","melhorias":"Propulsor longo: a investida chega a 9m.","cargas":"2","excl":["Corpo-a-Corpo"]},{"name":"Pistão Pneumático","tipo":"Bateria","pe":"1.5","acao":"Ação","mel":2,"desc":"Um aríete de ar comprimido preso ao braço. Gaste uma carga e escolha um alvo a até 1,5m. Ele faz um teste de resistência de Força (CD 10 + Proef + For). Na falha, é empurrado 6m para longe de você. Se bater numa parede, cobertura ou outro alvo, sofre 2d8 de dano contundente. Se for empurrado para fora de uma borda, cai.","melhorias":"Pressão máxima: o empurrão chega a 9m.\nGolpe duplo: o alvo que bater em algo também fica Caído.","cargas":"3","excl":["Corpo-a-Corpo"]},{"name":"\"TITAN GRIP\" Punho de Titã","tipo":"Vestido","pe":"1.5","acao":"Ação Livre","mel":2,"desc":"Uma manopla hidráulica. Os seus ataques desarmados causam +2 de dano, e você tem Vantagem nos testes de Força para agarrar e para abrir portas emperradas. Com a Reação, quando um ataque corpo a corpo acertar você, reduza o dano em 1d8 + For.","melhorias":"Propulsão cinética: com uma Ação Bônus, um soco empurra o alvo 3m (teste de Força, CD 10 + Proef + For, para resistir).\nGarra mecânica: ao acertar um ataque desarmado, você pode deixar o alvo Agarrado.","excl":["Corpo-a-Corpo"]},{"name":"Arnês de Retorno Magnético \"VÉRTEBRA\"","tipo":"Vestido","pe":"2","acao":"Ação Bônus","mel":3,"desc":"A lâmina corta, gira no ar e volta para as costas antes do inimigo cair.\nUm arnês de costas com ímãs e microdrones de sustentação. Ele carrega uma arma branca Leve ou Média, que flutua atrás de você. Sacar ou guardar essa arma não gasta Ação nem exige teste de Troca. Uma vez por turno, depois de atacar com a arma que está nas suas mãos, use a Ação Bônus para a arma do arnês atacar sozinha um alvo a até 3m de você, com Precisão igual à sua Proef + o atributo da arma. Esse ataque causa o dano da arma sem somar o modificador de atributo. Se você for desarmado, a arma volta para o arnês no fim do seu turno.","melhorias":"Arremesso de retorno: com uma Ação, a arma do arnês ataca um alvo a até 9m e volta para as suas costas logo depois, sem precisar ser recuperada.\nLâmina guardiã: quando um ataque corpo a corpo for acertar você, use a Reação para a arma do arnês aparar o golpe: você recebe +2 de CA contra esse ataque.\nSegunda lâmina: o arnês carrega duas armas brancas. Na Ação Bônus, as duas atacam, cada uma num alvo diferente a até 3m.","excl":["Corpo-a-Corpo"]},{"name":"Propulsor de Mergulho \"LANCEIRO\"","tipo":"Vestido / Bateria","pe":"2","acao":"Ação","mel":2,"desc":"Ele sobe. O inimigo olha para cima. É a última coisa que faz.\nGaste uma carga para saltar até 15m para cima, saindo do campo de batalha: até o início do seu próximo turno, você não pode ser alvo de ataques nem de efeitos. No início do seu próximo turno, você cai num ponto a até 12m de onde saltou e faz um ataque corpo a corpo contra um alvo a até 1,5m do ponto de queda. Num acerto, o ataque causa +3d6 de dano, e o alvo faz um teste de resistência de Força (CD 10 + Proef + For) para não ficar Caído. Você não sofre dano da queda.","melhorias":"Impacto: todos os outros alvos a até 2m do ponto de queda sofrem 1d6 de dano contundente.\nMergulho guiado: você pode cair a até 24m de onde saltou.","cargas":"2","excl":["Corpo-a-Corpo"]},{"name":"Estimulador C.Q.B.","tipo":"Consumível","pe":"1.25","acao":"Ação Livre","mel":2,"desc":"Um neuroestimulante para combate de perto. Por 2 turnos, você pode fazer um ataque corpo a corpo extra por turno com a Ação Bônus. Quando o efeito acaba, você fica com Desvantagem nos ataques até o fim do seu próximo turno.","melhorias":"Dose estendida: o efeito dura 3 turnos.\nCircuito de resfriamento: você não sofre a Desvantagem quando o efeito acaba.","qtd":"1","excl":["Corpo-a-Corpo"]},{"name":"Marcha \"Dureza\"","tipo":"Bateria","pe":"1","acao":"Ação Bônus","mel":2,"desc":"Um passo, outro passo. Ninguém fica para trás.\nUm alto-falante de ombro que toca uma marcha de cadência. Gaste uma carga para tocar a marcha por 1 minuto. Enquanto ela toca, os aliados a até 3m de você recebem +2m de Deslocamento e Vantagem nos testes de resistência contra Amedrontado. A área se move com você. Você não é afetado pela marcha.","melhorias":"Marcha de avanço: o bônus de Deslocamento sobe para +3m.\nCoro: o raio sobe para 6m.","cargas":"3","excl":["Comando"]},{"name":"Farol de Ataque Aéreo \"MEGAFLARE\"","tipo":"Bateria","pe":"3","acao":"Ação","mel":2,"desc":"Você aponta. Alguém, muito acima das nuvens, aperta um botão.\nVocê marca um ponto que possa ver a até 300m, ao ar livre. No fim do seu próximo turno, um ataque aéreo atinge um raio de 6m em volta dele. Cada alvo na área faz um teste de resistência de Destreza (CD 10 + Proef + Int). Na falha, sofre 6d10 de dano explosivo. No sucesso, sofre metade. Coberturas até Média na área são destruídas. Quem estiver no ponto marcado ouve o assobio chegando e pode tentar sair antes. O farol só funciona se houver apoio aéreo disponível: um avião ou drone de ataque do grupo, da facção ou de um contrato, em contato por rádio. Sem esse apoio, o farol não faz nada. Cada ataque gasta munição do apoio, que é cobrada à parte. A carga volta depois de um descanso longo.","melhorias":"Bombardeio de precisão: você escolhe até 3 alvos na área que não são atingidos.\nSegunda passagem: um turno depois do primeiro ataque, uma segunda passagem atinge o mesmo ponto com 3d10.","cargas":"1","excl":["Comando"]},{"name":"Bandeira de Comando","tipo":"Bateria","pe":"1.5","acao":"Ação Bônus","mel":2,"desc":"Enquanto a bandeira estiver de pé, ninguém recua.\nGaste uma carga para fincar a bandeira num ponto a até 1,5m. Por 1 minuto, os aliados a até 9m dela que possam vê-la somam 1d4 nas jogadas de ataque e nos testes de resistência. A bandeira tem CA 12 e 10 PV, e o efeito acaba se ela cair.","melhorias":"Mastro reforçado: a bandeira tem CA 15 e 25 PV.\nGrito de guerra: quando você finca a bandeira, cada aliado na área ganha 1d6 pontos de vida temporários.","cargas":"2","excl":["Comando"]},{"name":"Terminal Tático \"ORÁCULO\"","tipo":"Bateria","pe":"2","acao":"Ação Bônus","mel":2,"desc":"Quem vê o campo inteiro decide onde cada peça fica.\nUm terminal que mostra a posição de todos os aliados pareados num mapa tático. Uma vez por turno, com uma Ação Bônus, um aliado que você veja no terminal pode usar a Reação para se mover até 3m sem provocar ataques de oportunidade. Gaste uma carga para ordenar uma retirada: um aliado a até 30m sai do combate e vai para um ponto seguro que você marcou no mapa, sem provocar ataques, e só pode voltar ao combate no início do segundo turno dele.","melhorias":"Leitura de campo: os aliados pareados recebem +1 na CA contra ataques de oportunidade.\nRedeploy: o aliado retirado pode voltar já no início do próximo turno dele, a até 9m do ponto seguro.","cargas":"3","excl":["Comando"]},{"name":"Capacete com HUD","tipo":"Vestido / Bateria","pe":"1.25","acao":"Ação Livre","mel":2,"desc":"Um capacete com tela no visor ligada aos pontos e drones do grupo. Você vê no visor a posição dos aliados pareados, o que os drones e câmeras deles enxergam e a distância até qualquer alvo à vista. Você soma +1 na Iniciativa.","melhorias":"Assistente de mira: uma vez por turno, você ignora a penalidade de alcance de um disparo.\nFirewall militar: o Firewall do capacete recebe +3.","excl":["Comando"]},{"name":"Caixa de Suprimentos","tipo":"Consumível","pe":"1","acao":"Ação","mel":1,"desc":"Uma caixa lacrada de munição e explosivos. Com uma Ação, você abre a caixa, e até 5 aliados a até 3m dela repõem todos os pentes e recuperam 1 unidade de cada Lançável equipado.","melhorias":"Caixa médica: a caixa também tem curativos: cada aliado que usar recupera 1d6 PV.","qtd":"1","excl":["Comando"]},{"name":"Mina Incendiária","tipo":"Armadilha","pe":"1","acao":"Ação","mel":1,"desc":"Quando um alvo pisar na mina, ela explode num raio de 3m. Cada alvo na área faz um teste de resistência de Destreza (CD 10 + Proef + Des). Na falha, sofre 3d6 de dano incendiário e fica Queimado. No sucesso, sofre metade. A área queima por 1 minuto.","melhorias":"Combustível pesado: quem entrar na área em chamas ou começar o turno nela sofre 1d8 em vez de 1d6.","qtd":"1","excl":["Especialista"]},{"name":"Kit de Engenharia Rápida","tipo":"Bateria","pe":"2.5","acao":"Ação","mel":2,"desc":"Um drone de ferramentas que trabalha para você. Gaste uma carga para uma destas tarefas: montar uma granada, uma claymore ou uma C4 em 1 minuto, que você pode usar mesmo sem tê-la equipada; blindar uma parte de um veículo em 10 minutos; ou montar uma armadilha de laço ou uma rede de teto em 1 minuto.","melhorias":"Semeador de explosivos: ao montar uma granada, você junta o efeito de duas: a segunda não causa dano, só o efeito dela.\nBlindagem pessoal: uma tarefa pode dar a um aliado 5 + o seu nível em pontos de vida temporários, uma vez por pessoa por descanso longo.","cargas":"3","excl":["Especialista"]},{"name":"Robô de Alarme","tipo":"Bateria","pe":"1","acao":"Ação","mel":1,"desc":"Um robô pequeno que você posiciona num ponto. Ele vigia um raio de 9m. Quando um inimigo entrar na área, o robô avisa você e corre atrás dele. Se chegar a 1,5m, ele se agarra ao alvo e solta um pulso: o alvo fica vulnerável, e os ataques contra ele recebem +2 de Precisão até o fim do próximo turno dele. O robô tem CA 12 e 5 PV e pode ser destruído antes.","melhorias":"Pulso duplo: o robô solta o pulso duas vezes antes de desligar.","excl":["Especialista"]},{"name":"Munição de Choque","tipo":"Consumível (Munição)","pe":"0.75","acao":"Ação","mel":1,"desc":"Um pente de projéteis elétricos. Os disparos com ela causam dano elétrico, e um alvo atingido perde a Reação até o início do próximo turno dele. Mecanizados e alvos com Sistema interno também têm Desvantagem no próximo ataque.","melhorias":"Sobrecarga: um alvo com Sistema interno atingido também fica Atordoado até o fim do próximo turno dele, se falhar num teste de Constituição (CD 10 + Proef + Des).","qtd":"1","excl":["Especialista"]},{"name":"Kit de Reparo","tipo":"Consumível","pe":"1","acao":"Ação","mel":2,"desc":"Você repara um Construto a até 1,5m, como um Replika, um Mecanizado, um autômato ou um drone. Ele recupera 2d6 + Int pontos de vida. Também conserta um veículo em 1d6 + Int pontos de vida, com 10 minutos de trabalho.","melhorias":"Ferramentas de precisão: a cura sobe para 3d6 + Int.\nReparo em campo: consertar um veículo leva só 1 minuto.","qtd":"3","excl":["Especialista"]}];
